const SPELLS = [{"id":"MAG-0001","nomePt":"Proteção contra Lâminas","nomeEn":"Blade ward","nivel":0,"grupo":"Truque","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Abjuração","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"Pessoal","duracao":"Concentração, até 1 minuto","componentes":"V, S","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Defesa","funcao2":null,"prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Pacto da Lâmina (Pact of the Blade), Armadura de Agathys (Armor of Agathys) e builds de linha de frente que querem reduzir a frequência de acertos recebidos.","tradeoffs":"Exige Ação para iniciar e Concentração; compete com Bruxaria (Hex), Escuridão (Darkness) e outras magias de controle. Perde valor contra efeitos que não usam jogada de ataque.","melhorQuando":"Combates corpo a corpo contra vários inimigos que fazem muitas jogadas de ataque, quando sobreviver e preservar PV temporários vale mais que manter uma Concentração ofensiva.","perdeValor":"Perde prioridade assim que a Concentração passa a sustentar efeitos mais decisivos ou quando os inimigos usam salvaguardas em vez de ataques.","obs2024":"2024: Ação, alcance Pessoal, duração Concentração até 1 minuto. Sempre que uma criatura faz uma jogada de ataque contra você, ela subtrai 1d4 da jogada. Redesenhada em relação a 2014.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Protege você por até 1 minuto. Enquanto mantiver Concentração, ataques feitos contra você recebem uma penalidade de 1d4 na jogada de ataque.","notas":"Reduz a chance de você ser atingido ao impor -1d4 nas jogadas de ataque contra você. Funciona melhor em Bruxos que realmente esperam permanecer expostos.","nivelLabel":"Truque","funcoes":["Defesa"]},{"id":"MAG-0002","nomePt":"Toque Arrepiante","nomeEn":"Chill touch","nivel":0,"grupo":"Truque","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Necromancia","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"Toque","duracao":"Instantânea","componentes":"V, S","dano":"1d10 necrótico","material":"—","escalonamento":"+1d10 nos níveis 5, 11 e 17","funcao1":"Dano","funcao2":"Controle","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Bruxo sem foco no Pacto da Lâmina (Pact of the Blade) que precisa de uma resposta corpo a corpo e enfrenta inimigos com cura ou regeneração; pode aproveitar Invocações que aprimoram truques de dano, quando aplicáveis.","tradeoffs":"Exige ficar em alcance corpo a corpo e o bloqueio de cura só importa contra determinados inimigos. Para um Bruxo de arma dedicado, o Pacto da Lâmina normalmente oferece uma linha ofensiva melhor.","melhorQuando":"Inimigo que depende de cura ou regeneração e já está em alcance corpo a corpo do Bruxo.","perdeValor":"Como opção de dano padrão, perde espaço cedo para Rajada Mística; permanece relevante como ferramenta anti-cura.","obs2024":"2024: alcance Toque; ataque mágico corpo a corpo. Acerto causa 1d10 necrótico e impede o alvo de recuperar PV até o fim do seu próximo turno. Escala para 2d10/3d10/4d10 nos níveis 5/11/17.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Faz um ataque mágico corpo a corpo que causa dano necrótico e impede o alvo de recuperar Pontos de Vida até o fim do seu próximo turno.","notas":"Ataque corpo a corpo necrótico que impede o alvo de recuperar PV até o fim do seu próximo turno. É uma resposta de nicho contra cura e regeneração.","nivelLabel":"Truque","funcoes":["Dano","Controle"]},{"id":"MAG-0003","nomePt":"Rajada Mística","nomeEn":"Eldritch blast","nivel":0,"grupo":"Truque","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Evocação","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"36 m (120 ft)","duracao":"Instantânea","componentes":"V, S","dano":"1d10 força por raio","material":"—","escalonamento":"2 raios no nível 5; 3 no 11; 4 no 17","funcao1":"Dano","funcao2":"Controle","prioridadeN":4,"classificacao":"ESSENCIAL","sinergias":"Rajada Agonizante (Agonizing Blast), Rajada Repulsiva (Repelling Blast) e outras Invocações que transformam o truque no ataque padrão e em ferramenta de posicionamento do Bruxo.","tradeoffs":"Depende de jogadas de ataque e perde eficiência quando o Bruxo é pressionado em combate corpo a corpo. Extrair seu teto máximo costuma consumir escolhas de Invocação.","melhorQuando":"Combate sustentado à distância, com espaço para distribuir raios entre alvos e explorar dano consistente ou movimento forçado.","perdeValor":"Permanece relevante do nível 1 ao 20; o que muda é quanto da build você quer investir em aprimorá-la.","obs2024":"2024: 120 pés; ataque mágico à distância; 1d10 de Força. Ganha 2/3/4 raios nos níveis 5/11/17, com jogada de ataque separada para cada raio e possibilidade de dividir alvos.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Dispara um ou mais raios de energia que causam dano de força. A quantidade de raios aumenta com o nível, e cada raio faz sua própria jogada de ataque.","notas":"Ataque padrão do Bruxo à distância. Escala em múltiplos raios e cresce muito com Invocações como Rajada Agonizante (Agonizing Blast) e Rajada Repulsiva (Repelling Blast).","nivelLabel":"Truque","funcoes":["Dano","Controle"]},{"id":"MAG-0004","nomePt":"Amizade","nomeEn":"Friends","nivel":0,"grupo":"Truque","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"3 m (10 ft)","duracao":"Concentração, até 1 minuto","componentes":"S, M","dano":"—","material":"Maquiagem · sem custo · não consumida","escalonamento":"Não escala","funcao1":"Social","funcao2":"Controle","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Carisma alto, proficiência em Persuasão ou Enganação e personagens que atuam como face do grupo.","tradeoffs":"Usa Concentração, depende de salvaguarda e pode gerar consequências sociais quando o efeito termina. Tem pouco valor fora de cenas sociais adequadas.","melhorQuando":"Interação curta com uma criatura não hostil quando obter cooperação imediata vale mais que preservar a relação depois.","perdeValor":"Cai bastante em campanhas com pouca negociação, alvos não Humanoides ou quando a relação futura com o NPC importa.","obs2024":"2024: alcance 10 pés; Sabedoria evita Enfeitiçado. O alvo tem sucesso automático se não for Humanoide, se estiver lutando com você ou se foi alvo desta magia nas últimas 24h. O efeito pode terminar cedo por dano/ataques/salvaguardas e o alvo sabe que foi enfeitiçado quando termina.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Tenta Enfeitiçar um Humanoide não hostil por até 1 minuto, facilitando a interação social; ao final, o alvo percebe que foi afetado.","notas":"Ferramenta social curta para facilitar uma interação com um Humanoide não hostil, mas cobra um preço narrativo quando o efeito termina.","nivelLabel":"Truque","funcoes":["Social","Controle"]},{"id":"MAG-0005","nomePt":"Mãos Mágicas","nomeEn":"Mage hand","nivel":0,"grupo":"Truque","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"9 m (30 ft)","duracao":"1 minuto","componentes":"V, S","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Utilidade","funcao2":"Exploração","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Exploração cuidadosa, investigação, interação com mecanismos à distância e grupos que preferem testar objetos ou gatilhos sem expor um personagem.","tradeoffs":"Capacidade física limitada e pouco impacto direto em combate; ocupa uma das poucas escolhas de truque do Bruxo.","melhorQuando":"Manipular alavancas, objetos suspeitos, portas ou pequenos itens a distância durante exploração e resolução de problemas.","perdeValor":"Permanece relevante em toda a campanha; só perde prioridade se outra fonte da build já entregar a mesma função.","obs2024":"2024: mão espectral a 30 pés por 1 minuto. Pode manipular objetos, abrir recipientes/portas destrancados, guardar/retirar itens e derramar frascos; em turnos posteriores exige Ação Mágica para controlar. Não ataca, não ativa itens mágicos e carrega no máximo 10 lb.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Cria uma mão espectral a distância para manipular objetos, abrir recipientes, mover itens leves e realizar pequenas interações sem se aproximar.","notas":"Utilidade excelente para manipular objetos, abrir recipientes e testar mecanismos sem expor um personagem diretamente.","nivelLabel":"Truque","funcoes":["Utilidade","Exploração"]},{"id":"MAG-0006","nomePt":"Estilhaço Mental","nomeEn":"Mind sliver","nivel":0,"grupo":"Truque","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"18 m (60 ft)","duracao":"1 rodada","componentes":"V","dano":"1d6 psíquico","material":"—","escalonamento":"+1d6 nos níveis 5, 11 e 17","funcao1":"Controle","funcao2":"Dano","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Magias e habilidades que exigem salvaguarda, tanto do próprio Bruxo quanto de aliados; excelente preparação para controles importantes no turno seguinte.","tradeoffs":"Dano direto inferior a Rajada Mística (Eldritch Blast) e o valor do -1d4 depende de alguém aproveitar a próxima salvaguarda do alvo em tempo hábil.","melhorQuando":"Antes de uma magia de controle ou outro efeito decisivo baseado em salvaguarda, especialmente contra alvos com Inteligência baixa.","perdeValor":"Permanece útil como setup, mas perde prioridade quando você precisa de dano imediato ou ninguém consegue explorar o −1d4.","obs2024":"2024: 60 pés; salvaguarda de Inteligência. Falha causa 1d6 psíquico e -1d4 na próxima salvaguarda feita antes do fim do seu próximo turno. O dano escala nos níveis 5/11/17.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Ataca a mente de uma criatura com dano psíquico e, se ela falhar na salvaguarda, reduz em 1d4 a próxima salvaguarda que fizer.","notas":"Dano psíquico modesto, mas aplica -1d4 na próxima salvaguarda do alvo. Funciona como preparação para controles decisivos do Bruxo ou dos aliados.","nivelLabel":"Truque","funcoes":["Controle","Dano"]},{"id":"MAG-0007","nomePt":"Ilusão Menor","nomeEn":"Minor illusion","nivel":0,"grupo":"Truque","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Ilusão","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"9 m (30 ft)","duracao":"1 minuto","componentes":"S, M","dano":"—","material":"Pedaço de lã · sem custo · não consumido","escalonamento":"Não escala","funcao1":"Utilidade","funcao2":"Exploração","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Furtividade, infiltração, emboscadas e jogadores criativos que usam som ou imagem para desviar atenção, criar informação falsa ou manipular posicionamento.","tradeoffs":"Não causa dano e sua força depende bastante da criatividade, do contexto e da adjudicação do Mestre; inimigos podem investigar a ilusão.","melhorQuando":"Criar distrações, iscas visuais/sonoras ou cobertura narrativa durante exploração, infiltração e preparação de emboscadas.","perdeValor":"Permanece relevante, mas o valor depende muito do cenário e da criatividade; não substitui ilusões de nível superior.","obs2024":"2024: cria som ou imagem de objeto por 1 minuto em até 30 pés. Imagem cabe em Cubo de 5 pés. Uma criatura pode usar a ação Estudar e testar Inteligência (Investigação) contra sua CD; interação física revela a ilusão.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Cria um som ou uma imagem simples por até 1 minuto, útil para distrair, esconder, enganar ou simular pequenos elementos do ambiente.","notas":"Cria som ou imagem para distrair, enganar ou manipular atenção. O teto depende mais da criatividade e do contexto do que de poder bruto.","nivelLabel":"Truque","funcoes":["Utilidade","Exploração"]},{"id":"MAG-0008","nomePt":"Rajada de Veneno","nomeEn":"Poison spray","nivel":0,"grupo":"Truque","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Necromancia","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"9 m (30 ft)","duracao":"Instantânea","componentes":"V, S","dano":"1d12 veneno","material":"—","escalonamento":"+1d12 nos níveis 5, 11 e 17","funcao1":"Dano","funcao2":null,"prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Builds que aceitam lutar a curta distância e querem um dado de dano alto em um único ataque; pode aproveitar Invocações que aprimoram truques de dano, quando aplicáveis.","tradeoffs":"Alcance curto e dano de veneno encontram resistência ou imunidade com frequência; compete diretamente com o alcance, o tipo de dano e a escalabilidade de Rajada Mística (Eldritch Blast).","melhorQuando":"Alvos próximos sem resistência a veneno, especialmente nos níveis baixos quando o dado de dano alto pode compensar a menor flexibilidade.","perdeValor":"A partir do nível 5, Rajada Mística com Invocações tende a oferecer melhor alcance, consistência e múltiplos acertos.","obs2024":"2024: mudou para ataque mágico à distância de 30 pés; acerto causa 1d12 de veneno. Escala para 2d12/3d12/4d12 nos níveis 5/11/17.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Projeta veneno contra uma criatura a curta distância, causando dano de veneno com uma jogada de ataque mágico.","notas":"Ataque de curto alcance com dado alto de dano de veneno. É interessante cedo, mas perde terreno para Rajada Mística (Eldritch Blast) conforme o Bruxo escala.","nivelLabel":"Truque","funcoes":["Dano"]},{"id":"MAG-0009","nomePt":"Prestidigitação","nomeEn":"Prestidigitation","nivel":0,"grupo":"Truque","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Transmutação","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"3 m (10 ft)","duracao":"Até 1 hora","componentes":"V, S","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Utilidade","funcao2":"Social","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Interpretação, investigação, infiltração e resolução criativa de problemas; combina bem com outros truques utilitários sem consumir recursos de Magia de Pacto.","tradeoffs":"Quase nenhum impacto direto em combate e forte custo de oportunidade porque o Bruxo conhece poucos truques.","melhorQuando":"Campanhas com bastante exploração e interação social, nas quais pequenos efeitos mágicos recorrentes resolvem problemas sem gastar espaços de magia.","perdeValor":"Não fica mecanicamente pior, mas perde prioridade quando as poucas escolhas de truque precisam cobrir dano, controle ou outra utilidade mais recorrente na campanha.","obs2024":"2024: 10 pés; cria pequenos efeitos sensoriais, fogo, limpeza/sujeira, alteração de temperatura/sabor, marcas ou pequena criação. Pode manter até três efeitos não instantâneos ao mesmo tempo.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Produz pequenos efeitos mágicos — sons, odores, fogo, limpeza, marcas, alterações simples de temperatura ou sabor e pequenas criações — podendo manter até três efeitos não instantâneos ao mesmo tempo.","notas":"Canivete suíço narrativo para pequenos efeitos sensoriais e alterações simples no ambiente, ótimo para criatividade fora de combate.","nivelLabel":"Truque","funcoes":["Utilidade","Social"]},{"id":"MAG-0010","nomePt":"Trovoada","nomeEn":"Thunderclap","nivel":0,"grupo":"Truque","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Evocação","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"Pessoal · emanação 1,5 m (5 ft)","duracao":"Instantânea","componentes":"S","dano":"1d6 trovão em área","material":"—","escalonamento":"+1d6 nos níveis 5, 11 e 17","funcao1":"Dano","funcao2":"Controle","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Pacto da Lâmina (Pact of the Blade) e outras builds que permanecem próximas de vários inimigos; pode aproveitar Invocações que aprimoram truques de dano, quando aplicáveis.","tradeoffs":"Exige estar cercado ou muito próximo dos inimigos, usa salvaguarda de Constituição e produz ruído. A posição necessária é perigosa para muitos Bruxos.","melhorQuando":"Dois ou mais inimigos adjacentes ao Bruxo, com aliados fora da área e pouca necessidade de discrição.","perdeValor":"Perde prioridade quando o Bruxo consegue manter distância, quando os inimigos raramente se agrupam ao seu redor ou quando o ruído compromete a cena.","obs2024":"2024: alcance Pessoal com Emanação de 5 pés. Cada criatura na área faz salvaguarda de Constituição ou sofre 1d6 trovejante; o som é audível a 100 pés. Escala nos níveis 5/11/17.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Libera uma explosão de som ao seu redor que causa dano de trovão às criaturas próximas que falharem em uma salvaguarda de Constituição.","notas":"Dano em pequena área ao redor do Bruxo. Pode punir grupos adjacentes, mas exige uma posição normalmente arriscada para a classe.","nivelLabel":"Truque","funcoes":["Dano","Controle"]},{"id":"MAG-0011","nomePt":"Sino dos Mortos","nomeEn":"Toll the dead","nivel":0,"grupo":"Truque","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Necromancia","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"18 m (60 ft)","duracao":"Instantânea","componentes":"V, S","dano":"1d8 necrótico; 1d12 se o alvo já perdeu PV","material":"—","escalonamento":"+1 dado nos níveis 5, 11 e 17","funcao1":"Dano","funcao2":null,"prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Alvos já feridos, inimigos com CA alta e situações em que atacar uma salvaguarda de Sabedoria é melhor do que fazer uma jogada de ataque com Rajada Mística (Eldritch Blast).","tradeoffs":"É tudo ou nada na salvaguarda, não oferece os múltiplos raios nem o potencial de controle por Invocações de Rajada Mística.","melhorQuando":"Alvo já ferido, especialmente quando sua CA torna ataques menos atraentes e a salvaguarda de Sabedoria parece uma defesa mais fraca.","perdeValor":"Rajada Mística (Eldritch Blast) costuma ser superior como rotina principal; perde valor quando a CA do alvo é baixa, sua Sabedoria é alta ou o dano necrótico encontra resistência.","obs2024":"2024: 60 pés; salvaguarda de Sabedoria. Falha causa 1d8 necrótico, ou 1d12 se o alvo já perdeu qualquer PV. Escala um dado nos níveis 5/11/17. Incorporada ao núcleo do PHB 2024.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Faz soar um sino fúnebre sobre uma criatura, causando dano necrótico em falha na salvaguarda de Sabedoria; o dado de dano aumenta se o alvo já perdeu PV.","notas":"Salvaguarda de Sabedoria com dano necrótico que aumenta contra alvos já feridos. Boa alternativa quando uma CA alta torna jogadas de ataque menos atraentes.","nivelLabel":"Truque","funcoes":["Dano"]},{"id":"MAG-0012","nomePt":"Ataque Certeiro","nomeEn":"True strike","nivel":0,"grupo":"Truque","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Adivinhação","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"Pessoal","duracao":"Instantânea","componentes":"S, M","dano":"Dano da arma; pode ser radiante","material":"Arma proficiente de 1+ PC · reutilizável","escalonamento":"+1d6 radiante no nível 5; +2d6 no 11; +3d6 no 17","funcao1":"Dano","funcao2":null,"prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Personagem que quer fazer ataques ocasionais com arma usando o atributo de conjuração sem investir totalmente no Pacto da Lâmina (Pact of the Blade).","tradeoffs":"Exige uma arma e uma jogada de ataque; compete com Rajada Mística (Eldritch Blast) para conjuradores e com Pacto da Lâmina para builds marciais dedicadas.","melhorQuando":"Bruxo não especializado em arma que precisa transformar um ataque ocasional com arma em uma opção baseada no atributo de conjuração.","perdeValor":"Perde espaço em builds especializadas: Pacto da Lâmina (Pact of the Blade) já oferece suporte próprio a armas, enquanto Rajada Mística (Eldritch Blast) cobre melhor a rotina à distância.","obs2024":"2024: Pessoal; exige arma com a qual você tenha proficiência e valor 1+ PC. Faz um ataque usando o atributo de conjuração para ataque e dano; pode causar dano Radiante ou o tipo normal da arma. Ganha +1d6/+2d6/+3d6 Radiante nos níveis 5/11/17.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Permite fazer um ataque com uma arma usando seu atributo de conjuração para ataque e dano, podendo trocar o tipo normal da arma por Radiante e adicionando dano Radiante nos níveis superiores.","notas":"Permite atacar com arma usando o atributo de conjuração e adiciona dano Radiante conforme escala. Serve como solução ocasional, não como plano principal.","nivelLabel":"Truque","funcoes":["Dano"]},{"id":"MAG-0013","nomePt":"Armadura de Agathys","nomeEn":"Armor of Agathys","nivel":1,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Abjuração","concentracao":"Não","ritual":"Não","conjuracao":"Ação Bônus","alcance":"Pessoal","duracao":"1 hora","componentes":"V, S, M","dano":"5 frio ao atacante corpo a corpo","material":"Fragmento de vidro azul · sem custo · não consumido","escalonamento":"+5 PV temporários e +5 dano de frio por nível de espaço acima do 1º","funcao1":"Defesa","funcao2":"Dano","prioridadeN":4,"classificacao":"ESSENCIAL","sinergias":"Pacto da Lâmina (Pact of the Blade), builds de linha de frente e fontes adicionais de PV temporários; funciona especialmente bem quando o Bruxo espera receber ataques corpo a corpo.","tradeoffs":"Os PV temporários não se acumulam com outras fontes: ao receber novos PV temporários, você escolhe quais manter. O dano de retaliação depende de sofrer ataques corpo a corpo enquanto a magia ainda estiver ativa, então Bruxos de retaguarda podem extrair pouco valor ofensivo.","melhorQuando":"Bruxo de linha de frente ou Pacto da Lâmina (Pact of the Blade) que espera receber ataques corpo a corpo e quer combinar sobrevivência com dano de retaliação sem gastar Concentração.","perdeValor":"Permanece relevante por toda a progressão, mas perde bastante valor em encontros dominados por ataques à distância, salvaguardas ou inimigos que quase nunca acertam você corpo a corpo.","obs2024":"2024: Ação Bônus, alcance Pessoal, duração 1 hora. Concede 5 PV temporários; enquanto a magia estiver ativa, uma criatura que acertar você com ataque corpo a corpo sofre 5 de dano de frio. Termina cedo se você ficar sem PV temporários. Em espaço superior, PV temporários e dano aumentam em 5 por nível do espaço. Sage Advice 2024: os PV temporários que mantêm a magia ativa não precisam ter vindo da própria magia.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Reveste você com proteção gélida, concedendo PV temporários e causando dano de frio a criaturas que o acertarem com ataques corpo a corpo enquanto a magia estiver ativa.","notas":"Uma das melhores opções de combate para Bruxos que esperam ser atingidos: combina PV temporários com retaliação corpo a corpo sem ocupar Concentração e escala muito bem com os espaços de Magia de Pacto.","nivelLabel":"1º nível","funcoes":["Defesa","Dano"]},{"id":"MAG-0014","nomePt":"Braços de Hadar","nomeEn":"Arms of Hadar","nivel":1,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"Pessoal · emanação 3 m (10 ft)","duracao":"Instantânea","componentes":"V, S","dano":"2d6 necrótico em área; metade no sucesso","material":"—","escalonamento":"+1d6 por nível de espaço acima do 1º","funcao1":"Dano","funcao2":"Controle","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Pacto da Lâmina (Pact of the Blade) e Bruxos cercados que precisam abrir espaço; impedir Reações ajuda a sair do corpo a corpo depois da explosão.","tradeoffs":"Exige gastar um espaço de Magia de Pacto para um efeito de curto alcance e impacto imediato. O dano escala, mas a magia perde relevância quando surgem áreas e controles mais eficientes; entrar no meio de vários inimigos também aumenta o risco.","melhorQuando":"Quando o Bruxo está cercado por vários inimigos próximos e precisa causar dano em área enquanto bloqueia Reações para criar uma rota de fuga ou reposicionamento.","perdeValor":"Perde espaço rapidamente quando entram controles e áreas mais impactantes; também rende pouco quando você consegue evitar ser cercado ou quando os inimigos resistem bem à salvaguarda de Força.","obs2024":"2024: Ação, Emanação de 10 pés a partir de você, salvaguarda de Força. Falha: 2d6 necrótico e o alvo não pode usar Reações até o início do próximo turno; sucesso: metade do dano. Dano +1d6 por nível do espaço acima do 1º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Tentáculos sombrios explodem ao seu redor, causando dano necrótico em uma emanação e impedindo Reações dos alvos que falharem na salvaguarda.","notas":"Botão de emergência quando o Bruxo fica cercado. Atinge inimigos ao redor e pode cortar suas Reações, criando uma janela para escapar ou reposicionar.","nivelLabel":"1º nível","funcoes":["Dano","Controle"]},{"id":"MAG-0015","nomePt":"Perdição","nomeEn":"Bane","nivel":1,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"9 m (30 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S, M","dano":"—","material":"Gota de sangue · sem custo · não consumida","escalonamento":"+1 alvo por nível de espaço acima do 1º","funcao1":"Controle","funcao2":null,"prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Magias e habilidades do grupo que dependem de salvaguardas; reduzir jogadas de ataque e salvaguardas inimigas melhora tanto a defesa quanto o controle coletivo.","tradeoffs":"Usa Concentração e permite salvaguarda inicial, então compete diretamente com Bruxaria (Hex) e controles mais fortes. Seu valor cai quando o grupo não consegue aproveitar bem a penalidade de 1d4.","melhorQuando":"Combate contra vários inimigos importantes que dependem de jogadas de ataque ou salvaguardas, especialmente quando o grupo consegue explorar a penalidade de 1d4 por várias rodadas.","perdeValor":"Perde prioridade conforme a Concentração passa a competir com controles de 2º e 3º nível mais decisivos, ou quando o grupo não consegue explorar bem a penalidade de 1d4.","obs2024":"2024: Ação, 30 pés, Concentração até 1 minuto. Até 3 criaturas fazem salvaguarda de Carisma; em falha, subtraem 1d4 de jogadas de ataque e salvaguardas. Cada nível de espaço acima do 1º adiciona 1 alvo.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Afeta até três criaturas; cada alvo que falhar na salvaguarda de Carisma subtrai 1d4 de suas jogadas de ataque e salvaguardas enquanto você mantiver Concentração.","notas":"Debuff coletivo que reduz ataques e salvaguardas de vários inimigos. Fica especialmente interessante para Bruxos porque espaços maiores aumentam automaticamente o número de alvos.","nivelLabel":"1º nível","funcoes":["Controle"]},{"id":"MAG-0016","nomePt":"Enfeitiçar Pessoa","nomeEn":"Charm person","nivel":1,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"9 m (30 ft)","duracao":"1 hora","componentes":"V, S","dano":"—","material":"—","escalonamento":"+1 alvo por nível de espaço acima do 1º","funcao1":"Social","funcao2":"Controle","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Carisma alto, proficiência em Persuasão/Enganação e personagens que atuam como face do grupo; ganha valor em campanhas de intriga e negociação.","tradeoffs":"Depende de salvaguarda e de um alvo social apropriado; não substitui uma interação bem conduzida e pode gerar consequências quando o efeito termina. Em campanhas pouco sociais, ocupa uma escolha preparada com uso raro.","melhorQuando":"Cena social em que um Humanoide não hostil precisa ser influenciado rapidamente e o grupo aceita o risco de consequências depois que o efeito termina.","perdeValor":"Cai em campanhas com poucos Humanoides, alvos imunes a Enfeitiçado (Charmed), pouca interação social ou situações em que as consequências após o término importam mais que a vantagem imediata.","obs2024":"2024: Ação, 30 pés, duração 1 hora. Um Humanoide faz salvaguarda de Sabedoria, com Vantagem se estiver lutando contra você ou seus aliados. Em falha fica Enfeitiçado e Amigável; sabe que foi enfeitiçado quando o efeito termina. Upcast adiciona alvos.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Tenta Enfeitiçar um Humanoide por até 1 hora, fazendo-o ficar Enfeitiçado e Amigável em caso de falha na salvaguarda; ele percebe o encantamento quando o efeito termina.","notas":"Ferramenta social poderosa no contexto certo, mas limitada a Humanoides e com consequências claras depois. Funciona melhor em intriga e negociação do que como escolha universal.","nivelLabel":"1º nível","funcoes":["Social","Controle"]},{"id":"MAG-0017","nomePt":"Compreender Idiomas","nomeEn":"Comprehend languages","nivel":1,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Adivinhação","concentracao":"Não","ritual":"Sim","conjuracao":"Ação ou Ritual","alcance":"Pessoal","duracao":"1 hora","componentes":"V, S, M","dano":"—","material":"Pitada de fuligem e sal · sem custo · não consumida","escalonamento":"Não escala","funcao1":"Utilidade","funcao2":"Exploração","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Pacto do Tomo (Pact of the Tome), exploração, investigação e campanhas com idiomas, inscrições e documentos relevantes; o uso como Ritual reduz o custo em espaços.","tradeoffs":"É excelente quando linguagem realmente é um obstáculo, mas isso não acontece em todas as aventuras. Mesmo como Ritual, ainda ocupa uma magia preparada se vier da lista-base do Bruxo.","melhorQuando":"Exploração, investigação ou interação com inscrições, documentos e idiomas desconhecidos quando compreender a informação é mais importante que economizar tempo.","perdeValor":"Perde prioridade quando outro membro do grupo, item ou Pacto do Tomo cobre a mesma necessidade de forma confiável.","obs2024":"2024: Ação ou Ritual, Pessoal, duração 1 hora. Permite compreender o sentido literal de idiomas ouvidos, sinalizados e escritos; para escrita é preciso tocar a superfície. Não decodifica símbolos ou mensagens secretas.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Permite compreender o significado literal de idiomas falados, sinalizados e escritos durante 1 hora.","notas":"Ritual seguro para remover barreiras de idioma sem gastar espaço. Excelente quando pistas, inscrições e documentos importam; dispensável quando idiomas raramente criam obstáculos.","nivelLabel":"1º nível","funcoes":["Utilidade","Exploração"]},{"id":"MAG-0018","nomePt":"Detectar Magia","nomeEn":"Detect magic","nivel":1,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Adivinhação","concentracao":"Sim","ritual":"Sim","conjuracao":"Ação ou Ritual","alcance":"Pessoal · detecção 9 m (30 ft)","duracao":"Concentração, até 10 minutos","componentes":"V, S","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Exploração","funcao2":"Utilidade","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Pacto do Tomo (Pact of the Tome), exploração de masmorras e investigação de objetos/locais mágicos; Ritual permite uso recorrente sem gastar espaços de Magia de Pacto.","tradeoffs":"A utilidade é alta, mas normalmente não resolve encontros por si só. Se outro personagem já cobre detecção mágica ou se vier pelo Pacto do Tomo (Pact of the Tome), preparar a magia pela lista-base pode ser redundante.","melhorQuando":"Exploração de masmorras, ruínas e locais com magia ativa, especialmente quando ninguém no grupo já cobre detecção mágica de forma recorrente.","perdeValor":"Permanece útil; perde prioridade apenas quando a função já está coberta de forma constante por outro personagem, item ou recurso.","obs2024":"2024: Ação ou Ritual, Pessoal, Concentração até 10 minutos. Detecta efeitos mágicos a até 30 pés; com Ação Mágica revela aura em criatura/objeto visível e, se o efeito vier de magia, informa a escola. Certas espessuras de material bloqueiam a detecção.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Permite perceber magia próxima e, ao se concentrar em uma aura, identificar a escola de magia associada ao efeito.","notas":"Uma das ferramentas de exploração mais confiáveis do jogo. Como Ritual, permite investigar locais e objetos mágicos repetidamente sem consumir os preciosos espaços do Bruxo.","nivelLabel":"1º nível","funcoes":["Exploração","Utilidade"]},{"id":"MAG-0019","nomePt":"Recuo Acelerado","nomeEn":"Expeditious retreat","nivel":1,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Transmutação","concentracao":"Sim","ritual":"Não","conjuracao":"Ação Bônus","alcance":"Pessoal","duracao":"Concentração, até 10 minutos","componentes":"V, S","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Utilidade","funcao2":"Exploração","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Pacto da Lâmina (Pact of the Blade), estilo Skirmisher e builds que precisam entrar e sair do alcance inimigo; melhora reposicionamento e perseguição.","tradeoffs":"Exige Concentração para uma função que muitas vezes pode ser resolvida com posicionamento, teleporte ou outras opções. Compete com efeitos ofensivos e de controle e tem pouco impacto se mobilidade extra não for necessária.","melhorQuando":"Quando mobilidade é a prioridade imediata: perseguições, fugas, combate em mapas amplos ou build móvel que precisa usar Correr repetidamente sem gastar a Ação principal.","perdeValor":"Cai bastante quando entram Passo Nebuloso (Misty Step), Voo (Fly) e outras soluções de mobilidade mais decisivas.","obs2024":"2024: Ação Bônus, Pessoal, Concentração até 10 minutos. Você usa a ação Correr ao conjurar e, enquanto durar, pode usar Correr novamente como Ação Bônus.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Aumenta sua mobilidade ao permitir usar Disparada imediatamente e novamente como Ação Bônus enquanto mantiver Concentração.","notas":"Mobilidade sustentada para perseguições, fugas e builds móveis. O problema é pagar Concentração por algo que muitas vezes pode ser resolvido com posicionamento ou teleporte.","nivelLabel":"1º nível","funcoes":["Utilidade","Exploração"]},{"id":"MAG-0020","nomePt":"Repreensão Infernal","nomeEn":"Hellish rebuke","nivel":1,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Evocação","concentracao":"Não","ritual":"Não","conjuracao":"Reação ao sofrer dano de criatura visível a até 18 m (60 ft)","alcance":"18 m (60 ft)","duracao":"Instantânea","componentes":"V, S","dano":"2d10 fogo; metade no sucesso","material":"—","escalonamento":"+1d10 por nível de espaço acima do 1º","funcao1":"Dano","funcao2":"Defesa","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Armadura de Agathys (Armor of Agathys), Pacto da Lâmina (Pact of the Blade) e builds que já aceitam receber ataques; permite punir o agressor usando a Reação sem gastar a Ação do turno.","tradeoffs":"Gasta um dos poucos espaços de Magia de Pacto em uma Reação de dano único. Pode acabar consumindo recursos cedo demais em um dia de aventura e compete com outras Reações defensivas ou utilitárias.","melhorQuando":"Quando um inimigo já vai atingir o Bruxo e a melhor resposta é converter a Reação em dano imediato sem comprometer a Ação do próximo turno.","perdeValor":"O custo cresce conforme seus espaços de Pacto viram slots de 3º–5º nível que poderiam financiar controle ou defesa mais impactantes.","obs2024":"2024: Reação quando você sofre dano de uma criatura visível a até 60 pés. O agressor faz salvaguarda de Destreza; sofre 2d10 de fogo em falha ou metade no sucesso. Dano +1d10 por nível do espaço acima do 1º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Quando uma criatura causa dano a você, sua Reação envolve o agressor em chamas infernais, causando dano de fogo.","notas":"Converte sua Reação em dano imediato quando um inimigo machuca você, preservando sua Ação no turno seguinte. A economia de ações é ótima; a economia de espaços nem tanto.","nivelLabel":"1º nível","funcoes":["Dano","Defesa"]},{"id":"MAG-0021","nomePt":"Bruxaria","nomeEn":"Hex","nivel":1,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Sim","ritual":"Não","conjuracao":"Ação Bônus","alcance":"27 m (90 ft)","duracao":"Concentração, até 1 hora","componentes":"V, S, M","dano":"+1d6 necrótico em cada acerto com jogada de ataque","material":"Olho petrificado de tritão · sem custo · não consumido","escalonamento":"2º: até 4 h; 3º–4º: até 8 h; 5º+: até 24 h. O dano não aumenta.","funcao1":"Dano","funcao2":"Controle","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Rajada Mística (Eldritch Blast), múltiplos ataques do Pacto da Lâmina (Pact of the Blade) e qualquer build que faça várias jogadas de ataque por rodada; cada acerto aproveita o dano adicional.","tradeoffs":"Usa Concentração e seu dano adicional não aumenta com espaços de nível superior; o ganho de upcast é principalmente duração. Conforme o Bruxo ganha controles mais fortes, manter Hex pode ter custo de oportunidade alto.","melhorQuando":"Combates prolongados contra um alvo prioritário ou sequência de alvos, com várias jogadas de ataque por rodada por meio de Rajada Mística (Eldritch Blast) ou Pacto da Lâmina.","perdeValor":"A partir do acesso a magias de controle de 2º/3º nível, a disputa pela Concentração fica muito mais dura; continua ótima em rotinas de muitos ataques.","obs2024":"2024: Ação Bônus, 90 pés, Concentração até 1 hora. Cada acerto com jogada de ataque causa +1d6 necrótico ao alvo; também impõe Desvantagem em testes de uma habilidade escolhida. Se o alvo cair a 0 PV, a maldição pode ser transferida depois com Ação Bônus. Upcast aumenta a duração, não o dano.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Amaldiçoa uma criatura, causando dano necrótico extra sempre que você a acerta com um ataque e impondo Desvantagem em testes de uma habilidade escolhida.","notas":"Excelente base ofensiva para Bruxos que fazem várias jogadas de ataque. Cada acerto aproveita o +1d6, criando ótima sinergia com Rajada Mística (Eldritch Blast) e Pacto da Lâmina (Pact of the Blade).","nivelLabel":"1º nível","funcoes":["Dano","Controle"]},{"id":"MAG-0022","nomePt":"Escrita Ilusória","nomeEn":"Illusory script","nivel":1,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Ilusão","concentracao":"Não","ritual":"Sim","conjuracao":"1 minuto ou Ritual","alcance":"Toque","duracao":"10 dias","componentes":"S, M","dano":"—","material":"Tinta de 10+ PO · consumida","escalonamento":"Não escala","funcao1":"Utilidade","funcao2":"Social","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Pacto do Tomo (Pact of the Tome), espionagem, intriga política e campanhas em que mensagens, contratos ou documentos secretos tenham peso real.","tradeoffs":"É extremamente dependente da campanha: espionagem e documentos secretos podem torná-la útil, mas em muitas mesas quase nunca haverá uma situação em que justifique ocupar uma magia preparada.","melhorQuando":"Campanhas de espionagem, intriga ou política em que mensagens, contratos e documentos secretos realmente importam e podem ser interceptados por terceiros.","perdeValor":"Em campanhas de combate/exploração direta quase nunca justifica ocupar uma magia preparada.","obs2024":"2024: 1 minuto ou Ritual, Toque, duração 10 dias. Esconde ou altera texto para criaturas não designadas. Exige tinta de 10+ PO, consumida. Visão Verdadeira pode ler a mensagem oculta.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Escreve uma mensagem ilusória que pode parecer diferente para leitores não autorizados, escondendo conteúdo, idioma e caligrafia reais.","notas":"Ritual especializado para espionagem, documentos secretos e intriga. Pode ser excelente na campanha certa, mas quase inexistente em aventuras onde informação escrita não é relevante.","nivelLabel":"1º nível","funcoes":["Utilidade","Social"]},{"id":"MAG-0023","nomePt":"Proteção contra o Bem e o Mal","nomeEn":"Protection from evil and good","nivel":1,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Abjuração","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"Toque","duracao":"Concentração, até 10 minutos","componentes":"V, S, M","dano":"—","material":"Água benta de 25+ PO · consumida","escalonamento":"Não escala","funcao1":"Defesa","funcao2":"Controle","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Pacto da Lâmina (Pact of the Blade), Armadura de Agathys (Armor of Agathys) e proteção de aliados de linha de frente; ganha muito valor quando a campanha enfrenta frequentemente os tipos de criatura afetados.","tradeoffs":"É muito forte quando o tipo de criatura certo aparece, mas inútil contra muitos outros inimigos. Exige Concentração e componente material consumido, o que aumenta o custo de oportunidade para uma magia já situacional.","melhorQuando":"Campanhas ou encontros dominados por Aberrações, Celestiais, Elementais, Fadas, Ínferos ou Mortos-vivos, protegendo um aliado que será foco de ataques ou efeitos mentais.","perdeValor":"Cai para SITUACIONAL em campanhas onde os tipos protegidos aparecem pouco; o consumo de água benta também limita uso repetido.","obs2024":"2024: Ação, Toque, Concentração até 10 minutos. Aberrações, Celestiais, Elementais, Fadas, Ínferos e Mortos-vivos têm Desvantagem em ataques contra o alvo; também protege contra Possessão, Enfeitiçado e Amedrontado desses tipos. Consome Água Benta de 25+ PO.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Protege uma criatura contra Aberrações, Celestiais, Elementais, Fadas, Ínferos e Mortos-vivos, dificultando ataques e ajudando contra Enfeitiçado, Amedrontado e possessão.","notas":"Defesa extremamente forte contra determinados tipos de criatura, mas completamente dependente do matchup. Quando funciona, funciona muito; quando não funciona, não faz nada.","nivelLabel":"1º nível","funcoes":["Defesa","Controle"]},{"id":"MAG-0024","nomePt":"Falar com Animais","nomeEn":"Speak with animals","nivel":1,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Adivinhação","concentracao":"Não","ritual":"Sim","conjuracao":"Ação ou Ritual","alcance":"Pessoal","duracao":"10 minutos","componentes":"V, S","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Exploração","funcao2":"Social","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Pacto do Tomo (Pact of the Tome), exploração, viagens e investigação; excelente quando animais podem servir como fontes de pistas, reconhecimento ou informação ambiental.","tradeoffs":"O valor depende de haver animais relevantes e de quanto o Mestre permite que eles saibam ou comuniquem. Em aventuras urbanas, planares ou focadas em masmorras, pode passar longos períodos sem uso.","melhorQuando":"Viagens, exploração selvagem e investigação em ambientes onde animais podem fornecer pistas, rotas, perigos próximos ou testemunhos que o grupo não obteria de outra forma.","perdeValor":"Perde prioridade em ambientes sem Bestas, campanhas urbanas muito restritas ou quando outro personagem já cobre essa comunicação.","obs2024":"2024: Ação ou Ritual, Pessoal, duração 10 minutos. Permite compreender e conversar verbalmente com Bestas e usar as opções de perícia da ação Influenciar com elas. No mínimo, uma Besta pode relatar locais e monstros percebidos no último dia.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Permite compreender e se comunicar verbalmente com Bestas, usando-as como fontes de informação ou interlocutores.","notas":"Ritual de investigação e reconhecimento que transforma animais em fontes de informação. Brilha em viagens e exploração sem exigir gasto de espaço de magia.","nivelLabel":"1º nível","funcoes":["Exploração","Social"]},{"id":"MAG-0025","nomePt":"Risada Horrenda de Tasha","nomeEn":"Tasha’s Hideous Laughter","nivel":1,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"9 m (30 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S, M","dano":"—","material":"Torta e pena · sem custo · não consumidas","escalonamento":"+1 alvo por nível de espaço acima do 1º","funcao1":"Controle","funcao2":null,"prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Estilhaço Mental (Mind Sliver), aliados com debuffs de salvaguarda e progressão automática dos espaços de Magia de Pacto; espaços maiores permitem afetar mais alvos.","tradeoffs":"Usa Concentração e permite novas salvaguardas em certas condições, então o controle pode terminar cedo. Também compete com outras magias de controle importantes do Bruxo conforme os níveis aumentam.","melhorQuando":"Combate contra um ou mais alvos perigosos que dependem de ações para causar impacto e têm chance razoável de falhar em salvaguardas de Sabedoria; melhora ainda mais com upcast para múltiplos alvos.","perdeValor":"Permanece forte, mas perde prioridade contra grupos numerosos que pedem controle de área, inimigos com Sabedoria alta ou quando o grupo quebra o efeito cedo ao causar dano.","obs2024":"2024: Ação, 30 pés, Concentração até 1 minuto. Em falha na salvaguarda de Sabedoria, o alvo fica Caído e Incapacitado e não pode encerrar Caído por conta própria. Repete a salvaguarda no fim de cada turno e ao sofrer dano; dano concede Vantagem. Upcast adiciona 1 alvo por nível acima do 1º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Faz uma criatura cair em um acesso de riso, ficando Caída e Incapacitada se falhar na salvaguarda de Sabedoria, com novas tentativas para encerrar o efeito ao fim dos turnos e quando sofre dano.","notas":"Um dos melhores controles disponíveis já no 1º nível: pode deixar um inimigo Caído e Incapacitado, e os espaços crescentes do Bruxo permitem atingir mais alvos.","nivelLabel":"1º nível","funcoes":["Controle"]},{"id":"MAG-0026","nomePt":"Servo Invisível","nomeEn":"Unseen servant","nivel":1,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Não","ritual":"Sim","conjuracao":"Ação ou Ritual","alcance":"18 m (60 ft)","duracao":"1 hora","componentes":"V, S, M","dano":"—","material":"Pedaço de barbante e madeira · sem custo · não consumidos","escalonamento":"Não escala","funcao1":"Utilidade","funcao2":"Exploração","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Pacto do Tomo (Pact of the Tome), Mãos Mágicas (Mage Hand), exploração e resolução de problemas; oferece uma ferramenta persistente para tarefas simples sem gastar espaços quando usado como Ritual.","tradeoffs":"Fora de combate é excelente, mas em combate tem limitações claras de velocidade, força e ações disponíveis. Como Ritual, o custo em espaço é baixo, mas ainda pode competir por uma vaga de magia preparada se não vier do Tomo.","melhorQuando":"Exploração e resolução de problemas fora de combate, quando tarefas simples podem ser delegadas repetidamente sem expor personagens e sem gastar espaço se usada como Ritual.","perdeValor":"Permanece útil, mas pode ficar redundante quando familiar, Mãos Mágicas (Mage Hand) ou outras ferramentas já cobrem tarefas simples de exploração e interação.","obs2024":"2024: Ação ou Ritual, 60 pés, duração 1 hora. Cria uma força Média invisível, sem mente, com CA 10, 1 PV e Força 2, incapaz de atacar. Uma vez por turno, com Ação Bônus, pode ser comandada a mover até 15 pés e interagir com um objeto ou executar tarefa simples.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Cria um servo invisível e sem mente que executa tarefas simples, move objetos e interage com o ambiente sob seus comandos por até 1 hora.","notas":"Utilidade persistente por uma hora para tarefas simples, exploração e interação com objetos. Como Ritual, oferece bastante valor sem competir pelos espaços de Magia de Pacto.","nivelLabel":"1º nível","funcoes":["Utilidade","Exploração"]},{"id":"MAG-0027","nomePt":"Raio de Bruxa","nomeEn":"Witch bolt","nivel":1,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Evocação","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"18 m (60 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S, M","dano":"2d12 elétrico inicial; 1d12 automático por Ação Bônus nos turnos seguintes","material":"Galho atingido por relâmpago · sem custo · não consumido","escalonamento":"+1d12 no dano inicial por nível de espaço acima do 1º; dano recorrente permanece 1d12","funcao1":"Dano","funcao2":"Controle","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Rajada Mística (Eldritch Blast) e outras ações ofensivas nos turnos seguintes, pois o dano recorrente usa Ação Bônus; também se beneficia de aliados que dificultem a fuga do alvo e o mantenham dentro do alcance.","tradeoffs":"Exige Concentração e prende o valor da magia a um único alvo e a uma distância limitada. O dano recorrente não escala com espaços maiores, e se o alvo morrer, fugir ou quebrar a ligação, o investimento perde eficiência.","melhorQuando":"Combate contra um alvo resistente que tende a permanecer próximo por várias rodadas, permitindo aproveitar o dano inicial alto e o dano recorrente por Ação Bônus sem perder a Ação principal.","perdeValor":"Perde espaço quando o combate exige trocar de alvo, o inimigo é muito móvel, consegue sair do alcance ou quando sua Concentração precisa sustentar um efeito de impacto maior.","obs2024":"2024: Ação, 60 pés, Concentração até 1 minuto. Ataque mágico à distância causa 2d12 elétrico no acerto. Em turnos seguintes, Ação Bônus causa 1d12 elétrico automaticamente, mesmo se o ataque inicial errou. Termina se o alvo sair do alcance ou ganhar Cobertura Total. Upcast aumenta apenas o dano inicial em 1d12 por nível acima do 1º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Conecta você a um alvo com um arco de eletricidade; o ataque inicial causa dano elétrico e, nos turnos seguintes, você pode causar dano automático com Ação Bônus enquanto a ligação durar.","notas":"A versão 2024 virou uma opção real de dano sustentado: começa forte e depois causa dano automático com Ação Bônus, deixando sua Ação livre. É melhor contra alvos resistentes que permanecerão próximos.","nivelLabel":"1º nível","funcoes":["Dano","Controle"]},{"id":"MAG-0028","nomePt":"Nuvem de Adagas","nomeEn":"Cloud of daggers","nivel":2,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"18 m (60 ft) · cubo de 1,5 m (5 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S, M","dano":"4d4 cortante; pode repetir 1x por turno por criatura","material":"Lasca de vidro · sem custo · não consumida","escalonamento":"+2d4 por nível de espaço acima do 2º","funcao1":"Dano","funcao2":"Controle","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Rajada Repulsiva (Repelling Blast), empurrões, agarrões e outras formas de movimento forçado ajudam a manter ou recolocar inimigos dentro da área; a possibilidade de mover a nuvem nos turnos seguintes melhora ainda mais essa combinação.","tradeoffs":"Exige Concentração e ocupa um espaço de Magia de Pacto para uma área pequena. Embora possa ser movida nos turnos seguintes, reposicioná-la consome sua Ação Mágica, competindo diretamente com Rajada Mística (Eldritch Blast) e outras ações ofensivas.","melhorQuando":"Corredores, portas, gargalos ou áreas estreitas onde inimigos tenham dificuldade de sair da zona; fica ainda melhor quando o grupo consegue empurrar, bloquear ou reposicionar alvos de volta para a nuvem.","perdeValor":"Cai em mapas abertos ou contra inimigos muito móveis; se o grupo não consegue bloquear, empurrar ou reposicionar alvos na área, a zona pequena rende pouco.","obs2024":"2024: Ação, 60 pés, Cubo de 5 pés, Concentração até 1 minuto. Criaturas na área sofrem 4d4 cortante; o dano também ocorre ao entrar na área, terminar o turno nela ou quando o Cubo é movido para o espaço da criatura, no máximo uma vez por turno. Em turnos posteriores, uma Ação Mágica teleporta o Cubo até 30 pés. Upcast: +2d4 por nível acima do 2º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Cria uma pequena área de lâminas giratórias que causa dano cortante às criaturas na área; nos turnos seguintes, você pode mover a nuvem para outro espaço.","notas":"Zona pequena de dano recorrente que fica muito melhor com movimento forçado. Em 2024, você também pode reposicionar a nuvem, tornando-a bem mais flexível em gargalos e combates táticos.","nivelLabel":"2º nível","funcoes":["Dano","Controle"]},{"id":"MAG-0029","nomePt":"Coroa da Loucura","nomeEn":"Crown of madness","nivel":2,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"36 m (120 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S","dano":"Ataque corpo a corpo do próprio alvo contra outra criatura","material":"—","escalonamento":"Não escala","funcao1":"Controle","funcao2":null,"prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Estilhaço Mental (Mind Sliver) e outros efeitos que prejudicam salvaguardas ajudam a superar a salvaguarda inicial; ganha mais valor quando o alvo dominado está próximo de criaturas inimigas e pode aproveitar ataques corpo a corpo relevantes.","tradeoffs":"Depende de salvaguarda de Sabedoria e exige sua Ação nos turnos seguintes para manter o efeito ofensivo, reduzindo drasticamente sua economia de ação. Além disso, só funciona bem quando o alvo está perto de outra criatura que você queira que ele ataque.","melhorQuando":"Um inimigo fisicamente perigoso, com Sabedoria baixa e outro adversário adjacente que possa ser atingido por ele; cenário ideal quando sacrificar sua Ação por alguns turnos ainda gera vantagem líquida para o grupo.","perdeValor":"Perde espaço quando você tem controles que não exigem sua Ação a cada turno, quando o alvo não é Humanoide ou quando não há outra criatura próxima que ele possa atacar.","obs2024":"2024: Ação, 120 pés, Concentração até 1 minuto. Um Humanoide faz salvaguarda de Sabedoria; em falha fica Enfeitiçado e deve usar sua Ação antes de se mover para fazer um ataque corpo a corpo contra uma criatura escolhida por você, se houver alvo ao alcance. Repete a salvaguarda no fim de cada turno. Em turnos posteriores, você precisa usar a Ação Mágica para manter o controle.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Enfeitiça um Humanoide e pode forçá-lo a usar a própria Ação para atacar corpo a corpo uma criatura próxima escolhida por você enquanto o controle for mantido.","notas":"Controle de nicho que pode transformar um Humanoide perigoso em arma contra os próprios aliados. O preço é alto: exige Concentração, posicionamento certo e sua Ação para continuar comandando o efeito.","nivelLabel":"2º nível","funcoes":["Controle"]},{"id":"MAG-0030","nomePt":"Escuridão","nomeEn":"Darkness","nivel":2,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Evocação","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"18 m (60 ft) · esfera de 4,5 m (15 ft)","duracao":"Concentração, até 10 minutos","componentes":"V, M","dano":"—","material":"Pelo de morcego e pedaço de carvão · sem custo · não consumidos","escalonamento":"Não escala","funcao1":"Controle","funcao2":"Defesa","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Visão Diabólica (Devil’s Sight) é a principal sinergia: permite ao Bruxo operar normalmente dentro da escuridão mágica. Rajada Mística (Eldritch Blast), Pacto da Lâmina (Pact of the Blade) e posicionamento defensivo também podem explorar a diferença de visão.","tradeoffs":"Usa Concentração e pode prejudicar aliados que não enxergam em escuridão mágica. Sem Visão Diabólica (Devil’s Sight) ou planejamento de posicionamento, o controle do campo pode atrapalhar o próprio grupo tanto quanto os inimigos.","melhorQuando":"Bruxo com Visão Diabólica (Devil’s Sight) enfrentando inimigos que dependem de visão, especialmente em áreas onde controlar linhas de visão, ataques à distância e posicionamento seja mais importante que manter o campo livre para os aliados.","perdeValor":"Perde muito valor quando aliados dependem de visão, o mapa exige linhas de visão limpas ou o grupo não consegue explorar Visão Diabólica (Devil’s Sight) e posicionamento.","obs2024":"2024: Ação, 60 pés, Concentração até 10 minutos. Cria uma Esfera de 15 pés de Escuridão mágica; Visão no Escuro comum não atravessa e luz não mágica não ilumina. Pode ser conjurada em objeto não vestido/carregado, gerando uma Emanação móvel; cobrir o objeto bloqueia o efeito. Sobreposição com luz mágica de nível 2 ou menor dissipa essa luz.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Cria uma esfera de escuridão mágica que bloqueia visão comum e Visão no Escuro, podendo ser fixada em um objeto para mover a área com ele.","notas":"Controle forte de visão que fica excelente com Visão Diabólica (Devil’s Sight). Sem essa sinergia ou planejamento do grupo, pode atrapalhar seus aliados tanto quanto os inimigos.","nivelLabel":"2º nível","funcoes":["Controle","Defesa"]},{"id":"MAG-0031","nomePt":"Cativar","nomeEn":"Enthrall","nivel":2,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"18 m (60 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Controle","funcao2":"Exploração","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Máscara das Muitas Faces (Mask of Many Faces), furtividade e infiltração em grupo; funciona melhor quando o Bruxo assume o papel de distração enquanto aliados atravessam uma área observada.","tradeoffs":"O efeito é estreito e momentâneo: ajuda a esconder aliados de observadores específicos, mas não melhora diretamente os testes de Furtividade nem dura o bastante para exploração prolongada. Compete com opções de 2º nível muito mais impactantes.","melhorQuando":"Infiltração curta em que o Bruxo pode servir de distração para observadores enquanto aliados atravessam uma área vigiada sem precisar sustentar o efeito por muito tempo.","perdeValor":"Quase não serve em combate e perde prioridade quando Furtividade, Invisibilidade (Invisibility) ou outras soluções resolvem a infiltração com mais consistência.","obs2024":"2024: Ação, 60 pés, Concentração até 1 minuto. Criaturas escolhidas fazem salvaguarda de Sabedoria; criaturas que estejam lutando contra você ou seus companheiros têm sucesso automático. Em falha, sofrem -10 em testes de Sabedoria (Percepção) e Percepção Passiva pela duração.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Distrai criaturas escolhidas, impondo uma grande penalidade em Percepção e Percepção Passiva enquanto você mantiver Concentração.","notas":"Ferramenta de distração para infiltração: derruba fortemente a Percepção dos observadores. É útil em cenas específicas, mas estreita demais para competir com as melhores opções de 2º nível.","nivelLabel":"2º nível","funcoes":["Controle","Exploração"]},{"id":"MAG-0032","nomePt":"Imobilizar Pessoa","nomeEn":"Hold person","nivel":2,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"18 m (60 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S, M","dano":"—","material":"Pedaço reto de ferro · sem custo · não consumido","escalonamento":"+1 Humanoide por nível de espaço acima do 2º","funcao1":"Controle","funcao2":null,"prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Estilhaço Mental (Mind Sliver), aliados que atacam em corpo a corpo e Pacto da Lâmina (Pact of the Blade). A condição Paralisado torna o alvo muito mais vulnerável, e o upcast da Magia de Pacto permite aumentar o número de Humanoides afetados.","tradeoffs":"Afeta apenas Humanoides e depende de salvaguarda de Sabedoria, com novas salvaguardas ao fim dos turnos do alvo. Usa Concentração e pode falhar completamente contra criaturas de outros tipos ou inimigos com boa Sabedoria.","melhorQuando":"Combate contra um ou mais Humanoides perigosos, especialmente alvos corpo a corpo que podem ser rapidamente eliminados pelo grupo enquanto estão Paralisados; ganha muito valor quando o espaço superior permite atingir vários alvos.","perdeValor":"Cai a zero contra criaturas que não sejam Humanoides e perde eficiência contra Sabedoria alta ou quando controles mais amplos conseguem afetar o mesmo encontro.","obs2024":"2024: Ação, 60 pés, Concentração até 1 minuto. Um Humanoide faz salvaguarda de Sabedoria; em falha fica Paralisado. Repete a salvaguarda no fim de cada turno. Upcast: +1 Humanoide por nível de espaço acima do 2º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Paralisa um ou mais Humanoides que falharem na salvaguarda de Sabedoria, com novas salvaguardas ao fim de cada turno para encerrar o efeito.","notas":"Controle pesado contra Humanoides: Paralisado pode retirar um alvo perigoso da rodada e abrir uma janela para o grupo concentrar dano. Os espaços maiores do Bruxo ainda adicionam novos alvos.","nivelLabel":"2º nível","funcoes":["Controle"]},{"id":"MAG-0033","nomePt":"Invisibilidade","nomeEn":"Invisibility","nivel":2,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Ilusão","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"Toque","duracao":"Concentração, até 1 hora","componentes":"V, S, M","dano":"—","material":"Cílio em goma-arábica · sem custo · não consumido","escalonamento":"+1 criatura por nível de espaço acima do 2º","funcao1":"Exploração","funcao2":"Defesa","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Furtividade, reconhecimento e infiltração; os espaços crescentes de Magia de Pacto permitem incluir mais aliados. Pacto da Corrente (Pact of the Chain) e grupos voltados a exploração podem aproveitar bem a preparação e o posicionamento antes de encontros.","tradeoffs":"Usa Concentração e termina cedo quando o alvo ataca, causa dano ou conjura magia, o que limita o uso ofensivo. Em combate, normalmente funciona melhor como preparação, fuga ou reposicionamento do que como buff sustentado.","melhorQuando":"Exploração, infiltração, fuga ou preparação antes de combate, principalmente quando o upcast permite ocultar vários membros do grupo ao mesmo tempo.","perdeValor":"Permanece relevante por toda a campanha; perde eficiência em combate aberto, quando o grupo pretende atacar imediatamente ou quando outras formas de defesa e mobilidade resolvem melhor o problema.","obs2024":"2024: Ação, Toque, Concentração até 1 hora. O alvo recebe a condição Invisível. Termina imediatamente após o alvo fazer uma jogada de ataque, causar dano ou conjurar uma magia. Upcast: +1 criatura por nível de espaço acima do 2º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Torna uma criatura Invisível por até 1 hora, com o efeito terminando para ela quando fizer um ataque, causar dano ou conjurar uma magia.","notas":"Uma das melhores ferramentas de infiltração do nível. Dura até 1 hora e escala naturalmente com os espaços de Magia de Pacto, permitindo esconder mais aliados conforme o Bruxo progride.","nivelLabel":"2º nível","funcoes":["Exploração","Defesa"]},{"id":"MAG-0034","nomePt":"Espinho Mental","nomeEn":"Mind spike","nivel":2,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Adivinhação","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"36 m (120 ft)","duracao":"Concentração, até 1 hora","componentes":"S","dano":"3d8 psíquico; metade no sucesso","material":"—","escalonamento":"+1d8 por nível de espaço acima do 2º","funcao1":"Dano","funcao2":"Exploração","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Combina com perseguições e rastreamento de um alvo que pode tentar fugir ou esconder-se; funciona melhor quando o grupo consegue manter pressão sobre uma criatura específica depois do dano inicial.","tradeoffs":"Exige Concentração para um dano relativamente modesto e um benefício de rastreamento que só importa contra um alvo específico. Compete com Bruxaria (Hex), Escuridão (Darkness) e controles de maior impacto.","melhorQuando":"Perseguição de um alvo específico que tende a fugir, esconder-se ou tentar ficar invisível, quando o grupo valoriza manter a localização da criatura além do dano inicial.","perdeValor":"Cai quando rastreamento não importa, o alvo não pretende fugir ou se esconder, ou quando sua Concentração precisa sustentar Bruxaria (Hex), Escuridão (Darkness) ou controle mais decisivo.","obs2024":"2024: Ação, 120 pés, Concentração até 1 hora. Salvaguarda de Sabedoria; 3d8 psíquico em falha ou metade no sucesso. Em falha, você sempre sabe a localização do alvo enquanto estiverem no mesmo plano; ele não pode se esconder de você e não recebe benefício da condição Invisível contra você. Upcast: +1d8 por nível acima do 2º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Causa dano psíquico e, em falha na salvaguarda, permite rastrear continuamente o alvo no mesmo plano, impedindo que ele se esconda de você ou se beneficie de Invisibilidade contra você.","notas":"Dano psíquico com rastreamento persistente de um alvo específico. É útil contra fuga, ocultação e Invisibilidade, mas cobra Concentração por um benefício muito dependente do encontro.","nivelLabel":"2º nível","funcoes":["Dano","Exploração"]},{"id":"MAG-0035","nomePt":"Reflexos","nomeEn":"Mirror image","nivel":2,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Ilusão","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"Pessoal","duracao":"1 minuto","componentes":"V, S","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Defesa","funcao2":null,"prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Pacto da Lâmina (Pact of the Blade) e Bruxos que permanecem em alcance de ataques; como não exige Concentração, pode coexistir com Bruxaria (Hex), Escuridão (Darkness) ou outras magias sustentadas.","tradeoffs":"Não usa Concentração, mas consome uma Ação e um espaço de Magia de Pacto para defesa pessoal. Não melhora com espaços maiores e pode ser menos eficiente que Armadura de Agathys (Armor of Agathys) em builds que querem converter defesa em valor ofensivo.","melhorQuando":"Bruxo de linha de frente ou exposto a múltiplos ataques, quando defesa imediata sem Concentração é mais valiosa do que gastar a Ação em dano naquele turno.","perdeValor":"Perde valor quando a principal ameaça usa salvaguardas ou áreas em vez de ataques, quando a defesa pessoal não é necessária ou quando gastar uma Ação para preparar o efeito é caro demais.","obs2024":"2024: Ação, Pessoal, duração 1 minuto. Cria três duplicatas ilusórias. Quando um ataque acerta você, role 1d6 por duplicata restante; se qualquer dado resultar 3+, uma duplicata é atingida e destruída no lugar. Criaturas Cegas ou com Percepção às Cegas ou Visão Verdadeira ignoram o efeito.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Cria três duplicatas ilusórias que podem receber ataques em seu lugar, sendo destruídas uma a uma quando desviam um acerto.","notas":"Defesa pessoal forte sem Concentração. As duplicatas absorvem ataques que acertariam você, permitindo manter Bruxaria (Hex), Escuridão (Darkness) ou outro efeito sustentado ativo.","nivelLabel":"2º nível","funcoes":["Defesa"]},{"id":"MAG-0036","nomePt":"Passo Nebuloso","nomeEn":"Misty step","nivel":2,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Não","ritual":"Não","conjuracao":"Ação Bônus","alcance":"Pessoal · teleporte 9 m (30 ft)","duracao":"Instantânea","componentes":"V","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Defesa","funcao2":"Exploração","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Pacto da Lâmina (Pact of the Blade), estilo Skirmisher e qualquer Bruxo que precise escapar de corpo a corpo, atravessar terreno difícil por posicionamento ou alcançar altura/segurança sem usar a Ação principal.","tradeoffs":"Ação Bônus e ausência de Concentração são excelentes, mas a magia não escala com espaços superiores. Em níveis altos, gastar um espaço de Magia de Pacto de 4º ou 5º nível para o mesmo teleporte de 30 pés pode ter custo de oportunidade elevado.","melhorQuando":"Escapar de agarrões, cercos ou terreno perigoso; alcançar rapidamente uma posição elevada, cobertura, outro lado de obstáculo ou ponto tático sem provocar problemas de deslocamento normal.","perdeValor":"Permanece relevante por toda a campanha; perde eficiência apenas quando outra fonte de teleporte já cobre a necessidade ou quando gastar um espaço de Magia de Pacto alto por 30 pés é um custo excessivo.","obs2024":"2024: Ação Bônus, Pessoal, Instantânea. Teleporta você até 30 pés para um espaço desocupado que você possa ver. Não usa Concentração e não possui benefício de upcast.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Teleporta você instantaneamente até 30 pés para um espaço desocupado que consiga ver, usando Ação Bônus e sem exigir Concentração.","notas":"Teleporte de emergência com Ação Bônus e sem Concentração. Excelente para escapar, atravessar obstáculos e assumir posições táticas sem sacrificar sua Ação principal.","nivelLabel":"2º nível","funcoes":["Defesa","Exploração"]},{"id":"MAG-0037","nomePt":"Raio do Enfraquecimento","nomeEn":"Ray of enfeeblement","nivel":2,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Necromancia","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"18 m (60 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S","dano":"—; reduz dano do alvo em 1d8 em falha","material":"—","escalonamento":"Não escala","funcao1":"Controle","funcao2":null,"prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Armadura de Agathys (Armor of Agathys), linha de frente e aliados que querem reduzir o dano de um atacante físico perigoso; diminuir o dano inimigo ajuda a preservar PV temporários e a sobrevivência do grupo.","tradeoffs":"Usa Concentração e depende de salvaguarda de Constituição, justamente uma defesa frequentemente forte em inimigos físicos. Não escala com espaços superiores e compete com controles que podem neutralizar o alvo de forma mais completa.","melhorQuando":"Contra um atacante físico de alto dano que faça múltiplos ataques baseados em Força, especialmente quando reduzir o dano dele por várias rodadas vale mais do que tentar removê-lo completamente do combate.","perdeValor":"Perde prioridade conforme controles que incapacitam ou afetam vários alvos ficam disponíveis, e contra inimigos com Constituição alta ou pouco dependentes de dano baseado em Força.","obs2024":"2024: Ação, 60 pés, Concentração até 1 minuto. O alvo faz salvaguarda de Constituição. Em sucesso, tem Desvantagem na próxima jogada de ataque até o início do seu próximo turno. Em falha, tem Desvantagem em Testes d20 baseados em Força e subtrai 1d8 de todas as rolagens de dano; repete a salvaguarda ao fim de cada turno.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Enfraquece uma criatura: em falha na salvaguarda, impõe Desvantagem em Testes d20 baseados em Força e reduz suas rolagens de dano; mesmo no sucesso, prejudica o próximo ataque.","notas":"Debuff defensivo voltado a atacantes físicos. Em falha, reduz várias rolagens de dano; o problema é mirar Constituição justamente nos inimigos que mais justificariam a magia.","nivelLabel":"2º nível","funcoes":["Controle"]},{"id":"MAG-0038","nomePt":"Patas de Aranha","nomeEn":"Spider climb","nivel":2,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Transmutação","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"Toque","duracao":"Concentração, até 1 hora","componentes":"V, S, M","dano":"—","material":"Gota de betume e aranha · sem custo · não consumidas","escalonamento":"+1 criatura por nível de espaço acima do 2º","funcao1":"Exploração","funcao2":"Utilidade","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Rajada Mística (Eldritch Blast) e combate à distância a partir de paredes, tetos ou posições elevadas; também combina com exploração vertical e infiltração onde rotas convencionais são bloqueadas.","tradeoffs":"Usa Concentração para uma função de mobilidade que pode ser substituída por voo, teleporte, Invocações ou soluções mundanas. Não escala com espaços superiores e seu valor cai conforme outras opções de movimento entram na build.","melhorQuando":"Exploração vertical, infiltração por paredes/tetos, travessia de obstáculos ou combate à distância a partir de uma superfície inacessível a inimigos terrestres.","perdeValor":"A partir do acesso consistente a Voo (Fly), teleporte ou Invocações equivalentes, a Concentração exigida passa a custar mais do que a mobilidade oferecida.","obs2024":"2024: Ação, Toque, Concentração até 1 hora. Uma criatura voluntária pode se mover por superfícies verticais e tetos com as mãos livres e ganha Deslocamento de Escalada igual ao seu Deslocamento. Upcast: +1 criatura por nível de espaço acima do 2º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Concede a uma criatura velocidade de escalada igual ao Deslocamento e permite mover-se por paredes e tetos com as mãos livres.","notas":"Mobilidade vertical duradoura para exploração e posicionamento. Pode colocar vários aliados em paredes e tetos com upcast, mas disputa Concentração com opções de impacto maior.","nivelLabel":"2º nível","funcoes":["Exploração","Utilidade"]},{"id":"MAG-0039","nomePt":"Sugestão","nomeEn":"Suggestion","nivel":2,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"9 m (30 ft)","duracao":"Concentração, até 8 horas","componentes":"V, M","dano":"—","material":"Gota de mel · sem custo · não consumida","escalonamento":"Não escala","funcao1":"Controle","funcao2":"Social","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Carisma alto, Máscara das Muitas Faces (Mask of Many Faces), infiltração e campanhas sociais; funciona especialmente bem quando uma instrução bem formulada resolve um problema sem iniciar combate.","tradeoffs":"Depende de salvaguarda de Sabedoria, Concentração e de uma formulação cuidadosa da instrução. O efeito não pode exigir algo obviamente danoso ao alvo ou a seus aliados, e a interpretação da sugestão ainda depende bastante do contexto e da adjudicação do Mestre.","melhorQuando":"Situações sociais, infiltração, fuga, interrogatório ou combate em que uma instrução plausível e bem formulada possa remover um inimigo da cena, abrir acesso, entregar um objeto ou resolver o problema sem confronto direto.","perdeValor":"Permanece relevante, mas perde eficiência contra imunidade a Enfeitiçado (Charmed), alvos com Sabedoria alta, barreiras de comunicação ou situações em que a instrução plausível é difícil de formular.","obs2024":"2024: Ação, 30 pés, Concentração até 8 horas. Sugere em até 25 palavras uma atividade realizável a uma criatura que possa ouvir e entender você; não pode envolver dano óbvio ao alvo ou seus aliados. Em falha na salvaguarda de Sabedoria, fica Enfeitiçada e segue a sugestão até concluí-la, a duração terminar ou você/seus aliados causarem dano ao alvo.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Implanta uma sugestão curta e realizável na mente de uma criatura; em falha na salvaguarda, ela fica Enfeitiçada e segue a instrução enquanto o efeito durar ou até certas condições o encerrarem.","notas":"Controle social e tático extremamente flexível por até 8 horas. Uma sugestão bem formulada pode remover um inimigo da cena, conseguir acesso ou resolver um problema sem confronto direto.","nivelLabel":"2º nível","funcoes":["Controle","Social"]},{"id":"MAG-0040","nomePt":"Contramágica","nomeEn":"Counterspell","nivel":3,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Abjuração","concentracao":"Não","ritual":"Não","conjuracao":"Reação","alcance":"18 m (60 ft)","duracao":"Instantânea","componentes":"S","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Defesa","funcao2":"Controle","prioridadeN":4,"classificacao":"ESSENCIAL","sinergias":"Estilhaço Mental (Mind Sliver), Perdição (Bane) e outros efeitos que prejudiquem salvaguardas podem aumentar a chance de interromper o conjurador. Também cobre uma lacuna importante quando o grupo não possui outro personagem dedicado a negar magias.","tradeoffs":"Em 2024, o conjurador faz uma salvaguarda de Constituição, então o efeito não é garantido. Mesmo quando a interrupção funciona, um espaço usado pelo inimigo não é gasto; para o Bruxo, trocar um de seus poucos espaços de Magia de Pacto por essa interrupção pode ser caro.","melhorQuando":"Contra uma magia inimiga de alto impacto quando impedir a Ação naquele turno vale mais que preservar o espaço de Magia de Pacto, especialmente se o grupo não tiver outro usuário confiável de Contramágica.","perdeValor":"Permanece relevante, mas perde valor quando os inimigos quase não conjuram magias, usam efeitos que não podem ser interrompidos ou quando preservar o espaço de Magia de Pacto é mais importante que negar aquela ação.","obs2024":"2024: Reação ao ver uma criatura a até 60 pés conjurando uma magia com componente Verbal, Somático ou Material. O conjurador faz salvaguarda de Constituição; em falha, a magia não produz efeito e a ação usada para conjurá-la é perdida. Se foi usado um espaço de magia, esse espaço não é gasto.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Interrompe uma criatura que está conjurando uma magia; em falha na salvaguarda de Constituição, a magia não produz efeito e a Ação, Ação Bônus ou Reação usada para conjurá-la é desperdiçada, sem gastar o espaço de magia.","notas":"Resposta reativa de alto impacto contra conjuradores: troca sua Reação por uma chance de apagar a magia inimiga e desperdiçar a ação usada para conjurá-la. Em 2024, porém, o inimigo preserva o espaço de magia.","nivelLabel":"3º nível","funcoes":["Defesa","Controle"]},{"id":"MAG-0041","nomePt":"Dissipar Magia","nomeEn":"Dispel magic","nivel":3,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Abjuração","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"36 m (120 ft)","duracao":"Instantânea","componentes":"V, S","dano":"—","material":"—","escalonamento":"Slot superior encerra automaticamente magia de nível igual ou inferior ao slot","funcao1":"Controle","funcao2":"Utilidade","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"A progressão automática dos espaços de Magia de Pacto é especialmente valiosa: espaços maiores encerram automaticamente magias de nível igual ou inferior ao espaço usado, reduzindo a necessidade de testes contra efeitos mais fortes.","tradeoffs":"Usa sua Ação e um espaço de Magia de Pacto para responder a um efeito já existente. Só encerra magias em andamento, não todo efeito mágico, e pode ser redundante se outro conjurador do grupo já cobre essa função com mais espaços disponíveis.","melhorQuando":"Quando uma magia persistente está decidindo o encontro — controle, barreira, buff ou debuff — e encerrá-la imediatamente gera mais valor que usar a Ação para dano ou outro controle.","perdeValor":"Continua relevante em toda a campanha; só perde prioridade quando não há efeitos mágicos ativos que justifiquem o espaço.","obs2024":"2024: Ação, 120 pés, Instantânea. Encerra automaticamente magias em andamento de nível 3 ou menor no alvo. Para cada magia de nível 4+, exige teste com a habilidade de conjuração contra CD 10 + nível da magia. Com espaço superior, encerra automaticamente magias de nível igual ou menor ao espaço usado.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Encerra efeitos mágicos ativos em uma criatura, objeto ou área, removendo automaticamente magias de nível adequado e testando contra efeitos mais fortes.","notas":"Ferramenta de correção universal contra magias em andamento. No Bruxo, os espaços de Magia de Pacto mais altos ajudam a encerrar automaticamente efeitos de nível igual ou inferior ao espaço usado.","nivelLabel":"3º nível","funcoes":["Controle","Utilidade"]},{"id":"MAG-0042","nomePt":"Medo","nomeEn":"Fear","nivel":3,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Ilusão","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"Pessoal · cone de 9 m (30 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S, M","dano":"—","material":"Pena branca · sem custo · não consumida","escalonamento":"Não escala","funcao1":"Controle","funcao2":"Defesa","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Estilhaço Mental (Mind Sliver) e outros debuffs de salvaguarda ajudam no teste inicial de Sabedoria. O deslocamento forçado dos inimigos para longe cria espaço para Rajada Mística (Eldritch Blast), aliados à distância e reposicionamento do grupo.","tradeoffs":"Exige Concentração e um Cone de 30 pés a partir do Bruxo, o que pede posicionamento relativamente próximo e pode incluir aliados. Inimigos que conseguem terminar o turno sem linha de visão para você recebem nova salvaguarda e podem encerrar o efeito.","melhorQuando":"Contra vários inimigos agrupados quando abrir distância, quebrar a linha inimiga e consumir os turnos deles com Correr tem mais valor que causar dano imediato.","perdeValor":"Perde prioridade quando controles que removem ações ou afetam alvos sem depender de visão entregam resultado mais consistente.","obs2024":"2024: Ação, Cone de 30 pés a partir de você, Concentração até 1 minuto. Em falha na salvaguarda de Sabedoria, a criatura larga o que segura e fica Amedrontada; em seus turnos usa Correr e se afasta pela rota mais segura. Se terminar o turno sem linha de visão para você, repete a salvaguarda.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Projeta uma onda de terror em cone, fazendo criaturas que falharem na salvaguarda largarem o que seguram e fugirem enquanto estiverem Amedrontadas.","notas":"Controle em cone que desmonta a linha inimiga, força deslocamento para longe e pode consumir turnos inteiros com Correr. Excelente quando abrir espaço vale mais que dano imediato.","nivelLabel":"3º nível","funcoes":["Controle","Defesa"]},{"id":"MAG-0043","nomePt":"Voar","nomeEn":"Fly","nivel":3,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Transmutação","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"Toque","duracao":"Concentração, até 10 minutos","componentes":"V, S, M","dano":"—","material":"Pena · sem custo · não consumida","escalonamento":"+1 criatura por nível de espaço acima do 3º","funcao1":"Exploração","funcao2":"Utilidade","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Rajada Mística (Eldritch Blast) pode aproveitar posições aéreas e linhas de tiro melhores; Pacto da Lâmina (Pact of the Blade) ganha acesso a alvos voadores. Os espaços crescentes de Magia de Pacto adicionam mais aliados como alvos.","tradeoffs":"Exige Concentração; perder a Concentração enquanto o alvo está no ar pode provocar queda. A conjuração é por Toque e, em combate, manter Voo compete diretamente com controles fortes como Fome de Hadar (Hunger of Hadar) e Padrão Hipnótico (Hypnotic Pattern).","melhorQuando":"Combates com forte componente vertical, inimigos voadores, obstáculos intransponíveis ou exploração em que mobilidade aérea para um ou mais membros do grupo muda completamente a abordagem.","perdeValor":"Continua relevante, mas perde prioridade quando a campanha oferece voo permanente, montarias voadoras ou outra fonte confiável de mobilidade.","obs2024":"2024: Ação, Toque, Concentração até 10 minutos. O alvo recebe Deslocamento de Voo de 60 pés e pode pairar; se a magia terminar enquanto ainda estiver no ar, cai caso não possa impedir a queda. Upcast: +1 criatura por nível de espaço acima do 3º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Concede voo a uma criatura por até 10 minutos, permitindo deslocamento aéreo e pairar enquanto você mantiver Concentração.","notas":"Mobilidade que muda o mapa: acesso a inimigos voadores, rotas impossíveis e posições seguras. Os espaços maiores do Bruxo ainda permitem levar aliados junto.","nivelLabel":"3º nível","funcoes":["Exploração","Utilidade"]},{"id":"MAG-0044","nomePt":"Forma Gasosa","nomeEn":"Gaseous form","nivel":3,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Transmutação","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"Toque","duracao":"Concentração, até 1 hora","componentes":"V, S, M","dano":"—","material":"Pedaço de gaze · sem custo · não consumido","escalonamento":"+1 criatura por nível de espaço acima do 3º","funcao1":"Exploração","funcao2":"Defesa","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Pacto da Corrente (Pact of the Chain), reconhecimento e exploração de áreas inacessíveis; funciona bem quando o grupo precisa transformar um único personagem em infiltrador resistente capaz de atravessar frestas estreitas.","tradeoffs":"Exige Concentração e reduz drasticamente a capacidade de agir: Deslocamento de Voo de apenas 10 pés, sem falar ou manipular objetos. É excelente para infiltração ou fuga, mas quase sempre sacrifica participação ofensiva enquanto estiver ativa.","melhorQuando":"Exploração de passagens estreitas, fuga de confinamento, infiltração por frestas ou travessia segura de áreas onde resistência física e mobilidade não convencional são mais importantes que velocidade.","perdeValor":"Perde espaço quando teleporte, voo ou outras formas de mobilidade resolvem o problema sem impedir ataque e conjuração.","obs2024":"2024: Ação, Toque, Concentração até 1 hora. Uma criatura voluntária vira uma nuvem; recebe Voo 10 pés com pairar, resistência a dano Contundente/Perfurante/Cortante, imunidade a Caído e Vantagem em salvaguardas de Força, Destreza e Constituição. Pode atravessar aberturas estreitas, mas não falar nem manipular objetos.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Transforma uma criatura em névoa, permitindo voo lento, passagem por pequenas frestas e maior resistência, mas impedindo ataques e conjuração.","notas":"Ferramenta forte de infiltração e fuga: atravessa frestas, paira e ganha várias resistências defensivas. O preço é praticamente abrir mão de agir ofensivamente enquanto a forma durar.","nivelLabel":"3º nível","funcoes":["Exploração","Defesa"]},{"id":"MAG-0045","nomePt":"Fome de Hadar","nomeEn":"Hunger of Hadar","nivel":3,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"45 m (150 ft) · esfera de raio 6 m (20 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S, M","dano":"2d6 frio + 2d6 ácido por rodada, conforme posição","material":"Tentáculo em conserva · sem custo indicado · não consumido","escalonamento":"+1d6 para frio ou ácido por nível de espaço acima do 3º","funcao1":"Controle","funcao2":"Dano","prioridadeN":4,"classificacao":"ESSENCIAL","sinergias":"Rajada Repulsiva (Repelling Blast), empurrões, puxões e bloqueio de rotas ajudam a manter inimigos dentro da esfera. A combinação de Escuridão, terreno difícil, Cegueira e dano recorrente transforma controle de movimento em dano adicional.","tradeoffs":"Exige Concentração, ocupa uma área fixa e afeta qualquer criatura que permaneça nela, inclusive aliados. Inimigos com boa mobilidade podem sair da esfera, então seu valor depende bastante do mapa e da capacidade do grupo de controlar deslocamento.","melhorQuando":"Corredores, portas, gargalos e grupos de inimigos que precisam atravessar uma zona específica; especialmente forte quando o grupo consegue impedir a saída ou devolver inimigos para a área.","perdeValor":"Continua forte, mas perde valor se o próprio grupo não consegue trabalhar com a área de escuridão ou se o encontro espalha os inimigos.","obs2024":"2024: Ação, 150 pés, Esfera de 20 pés, Concentração até 1 minuto. A área é Escuridão e terreno difícil; criaturas totalmente dentro ficam Cegas. Quem inicia o turno nela sofre 2d6 de frio; quem termina faz salvaguarda de Destreza ou sofre 2d6 de ácido. Upcast: aumenta em 1d6, por nível acima do 3º, o dano de frio ou ácido à sua escolha.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Abre uma esfera de escuridão sobrenatural cheia de frio e tentáculos, cegando criaturas dentro dela e causando dano de frio e ácido.","notas":"Controle de campo assinatura do Bruxo: combina Escuridão, terreno difícil, Cegueira e dano recorrente numa área grande. Fica brutal quando o grupo consegue prender ou empurrar inimigos de volta para a esfera.","nivelLabel":"3º nível","funcoes":["Controle","Dano"]},{"id":"MAG-0046","nomePt":"Padrão Hipnótico","nomeEn":"Hypnotic pattern","nivel":3,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Ilusão","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"36 m (120 ft) · cubo de 9 m (30 ft)","duracao":"Concentração, até 1 minuto","componentes":"S, M","dano":"—","material":"Uma pitada de confete · sem custo · não consumida","escalonamento":"Não escala","funcao1":"Controle","funcao2":null,"prioridadeN":4,"classificacao":"ESSENCIAL","sinergias":"Funciona melhor quando o grupo coordena foco em alvos não afetados e evita causar dano aos Incapacitados. Estilhaço Mental (Mind Sliver) e debuffs de Sabedoria podem melhorar a chance de remover vários inimigos da luta de uma vez.","tradeoffs":"Exige Concentração, não melhora com espaços superiores e depende da condição Enfeitiçado; criaturas imunes a Enfeitiçado ignoram o principal efeito. Qualquer dano ou uma Ação de outra criatura pode libertar um alvo afetado.","melhorQuando":"Encontro com muitos inimigos visíveis e agrupados, quando o grupo consegue neutralizar parte do campo e derrotar os restantes sem tocar nos alvos hipnotizados.","perdeValor":"Perde valor quando inimigos estão espalhados, são imunes a Charmed ou quando o grupo precisa causar dano indiscriminado imediatamente.","obs2024":"2024: Ação, 120 pés, Cubo de 30 pés, Concentração até 1 minuto. Criaturas que veem o padrão fazem salvaguarda de Sabedoria; em falha ficam Enfeitiçadas, Incapacitadas e com Deslocamento 0. O efeito termina para uma criatura se ela sofrer dano ou se outra criatura usar uma Ação para despertá-la.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Cria um padrão visual hipnótico em uma grande área; criaturas que falharem ficam Enfeitiçadas, Incapacitadas e com deslocamento 0 até o efeito ser quebrado.","notas":"Um dos controles coletivos mais eficientes do nível: pode retirar vários inimigos da luta de uma vez, desde que o grupo evite acordá-los com dano.","nivelLabel":"3º nível","funcoes":["Controle"]},{"id":"MAG-0047","nomePt":"Círculo Mágico","nomeEn":"Magic circle","nivel":3,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Abjuração","concentracao":"Não","ritual":"Não","conjuracao":"1 minuto","alcance":"3 m (10 ft) · cilindro de raio 3 m (10 ft) e altura 6 m (20 ft)","duracao":"1 hora","componentes":"V, S, M","dano":"—","material":"Sal e prata em pó de 100+ PO · consumidos","escalonamento":"+1 hora de duração por nível de espaço acima do 3º","funcao1":"Defesa","funcao2":"Controle","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Combina especialmente com Vinculação Planar (Planar Binding) e situações preparadas envolvendo Celestiais, Elementais, Fadas, Ínferos ou Mortos-vivos; a versão invertida permite transformar proteção em contenção.","tradeoffs":"Tempo de conjuração de 1 minuto, área fixa e componente de 100+ PO consumido tornam o uso improvisado em combate pouco prático. Só afeta categorias específicas de criaturas e ocupa uma escolha preparada para uma necessidade rara.","melhorQuando":"Rituais preparados, interrogatórios, contenção de entidade extraplanar ou defesa antecipada de um local quando você conhece o tipo de criatura que enfrentará e tem tempo para montar o círculo.","perdeValor":"Perde prioridade em encontros comuns ou quando o custo material e o tempo de conjuração não compensam.","obs2024":"2024: 1 minuto, 10 pés, duração 1 hora. Cria Cilindro de raio 10 pés e altura 20 pés contra Celestiais, Elementais, Fadas, Ínferos e/ou Mortos-vivos: restringe entrada, impõe Desvantagem em ataques contra alvos dentro e protege contra Possessão, Enfeitiçado e Amedrontado. Pode ser invertido para conter. Consome sal/prata de 100+ PO; upcast aumenta a duração em 1 hora por nível.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Cria um círculo de proteção ou contenção contra certos tipos de criaturas, dificultando sua entrada, saída, ataques e efeitos mentais.","notas":"Ferramenta de preparação, não de improviso. Protege uma área ou aprisiona certos tipos de criatura, sendo muito mais valiosa em rituais, contenção e encontros planejados.","nivelLabel":"3º nível","funcoes":["Defesa","Controle"]},{"id":"MAG-0048","nomePt":"Imagem Maior","nomeEn":"Major image","nivel":3,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Ilusão","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"36 m (120 ft) · cubo de até 6 m (20 ft)","duracao":"Concentração, até 10 minutos","componentes":"V, S, M","dano":"—","material":"Pedaço de lã · sem custo · não consumido","escalonamento":"Com slot de 4º+ nível, dura até ser dissipada e não exige Concentração","funcao1":"Utilidade","funcao2":"Controle","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Máscara das Muitas Faces (Mask of Many Faces), infiltração e builds de engano aproveitam muito a ilusão multissensorial. Para o Bruxo, a progressão automática da Magia de Pacto é especial: com espaço de 4º+ nível, a imagem dura até ser dissipada e deixa de exigir Concentração.","tradeoffs":"No 3º nível exige Concentração e o efeito depende de criatividade e adjudicação. Interação física revela a ilusão, e uma criatura pode usar Estudar para identificá-la; além disso, a imagem não causa dano nem condições diretamente.","melhorQuando":"Infiltração, distração, criação de falsas ameaças ou obstáculos e manipulação de informação visual; a partir de espaços de 4º nível, excelente para estabelecer ilusões persistentes sem Concentração.","perdeValor":"Perde prioridade quando a campanha oferece poucas oportunidades de infiltração ou manipulação social; continua relevante para criatividade.","obs2024":"2024: Ação, 120 pés, Concentração até 10 minutos. Cria fenômeno ilusório de até Cubo de 20 pés com aparência, sons, cheiros e temperatura apropriados; pode ser movido com Ação Mágica. Interação física revela a ilusão e Estudar pode identificá-la. Com espaço de 4º+ nível, dura até ser dissipada e não exige Concentração.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Cria uma ilusão grande e convincente com imagem, som, cheiro e temperatura, que pode ser movida e controlada enquanto durar.","notas":"Ilusão multissensorial extremamente flexível. Para o Bruxo fica ainda melhor a partir de espaços de 4º nível, quando passa a durar até ser dissipada sem exigir Concentração.","nivelLabel":"3º nível","funcoes":["Utilidade","Controle"]},{"id":"MAG-0049","nomePt":"Remover Maldição","nomeEn":"Remove curse","nivel":3,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Abjuração","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"Toque","duracao":"Instantânea","componentes":"V, S","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Defesa","funcao2":"Utilidade","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Funciona como resposta de emergência para efeitos que o grupo não consegue resolver por outros meios e ganha valor em campanhas com itens amaldiçoados, licantropia ou maldições recorrentes.","tradeoffs":"Uso muito dependente da campanha e compete por uma magia preparada do Bruxo. Em item mágico amaldiçoado, não remove a maldição do item: apenas quebra a Sintonia do portador para que ele possa removê-lo ou descartá-lo.","melhorQuando":"Quando uma maldição já está prejudicando um personagem ou quando é necessário quebrar imediatamente a Sintonia com um item amaldiçoado e não há outro conjurador capaz de resolver o problema.","perdeValor":"Pode ficar muito tempo sem ser conjurada em campanhas onde maldições são raras ou quando outro personagem já cobre remoção de maldições de forma mais eficiente.","obs2024":"2024: Ação, Toque, Instantânea. Encerra todas as maldições afetando uma criatura ou objeto. Em item mágico amaldiçoado, a maldição do item permanece, mas a magia quebra a Sintonia do portador para permitir remover ou descartar o item.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Encerra maldições que afetam uma criatura ou objeto; em um item mágico amaldiçoado, rompe a Sintonia do portador sem remover a maldição do item.","notas":"Resposta especializada para maldições já em curso. Pode salvar uma situação crítica, mas normalmente ocupa uma escolha de magia para um problema que talvez nem apareça na campanha.","nivelLabel":"3º nível","funcoes":["Defesa","Utilidade"]},{"id":"MAG-0050","nomePt":"Invocar Fada","nomeEn":"Summon fey","nivel":3,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"27 m (90 ft)","duracao":"Concentração, até 1 hora","componentes":"V, S, M","dano":"2d6 + 6 força por ataque no 3º círculo; 1 ataque no slot 3","material":"Flor dourada de 300+ PO · não consumida","escalonamento":"O nível do espaço usado define o nível da magia no bloco do Espírito Feérico","funcao1":"Dano","funcao2":"Utilidade","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"A progressão automática dos espaços de Magia de Pacto melhora diretamente o bloco da Fada. As três formas de humor oferecem flexibilidade tática, e um aliado adicional em campo melhora ocupação de espaço, pressão e controle sem exigir Ações para comandar.","tradeoffs":"Exige Concentração por até 1 hora e um componente de 300+ PO, embora não seja consumido. Perder Concentração encerra o espírito, e manter a invocação impede usar simultaneamente controles como Fome de Hadar ou Padrão Hipnótico.","melhorQuando":"Aventuras com vários encontros entre descansos curtos ou combates prolongados em que um aliado adicional por até 1 hora consegue gerar dano e utilidade repetidos, aproveitando o upcast automático do Bruxo.","perdeValor":"Perde prioridade quando sua Concentração precisa sustentar um controle de área decisivo, quando o espírito não consegue sobreviver tempo suficiente ou quando o combate termina rápido demais para recuperar o investimento.","obs2024":"2024: Ação, 90 pés, Concentração até 1 hora. Invoca um Espírito Feérico e escolhe humor Fuming, Mirthful ou Tricksy, que altera detalhes do bloco. Age logo após você na mesma Iniciativa e obedece comandos verbais sem Ação. Exige flor dourada de 300+ PO, não indicada como consumida. O nível do espaço usado define o nível da magia no bloco.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Invoca um espírito feérico que luta ao seu lado por até 1 hora, com diferentes características conforme o humor escolhido e obedecendo a seus comandos verbais.","notas":"Invocação sustentada e versátil que adiciona outro corpo ao campo por até 1 hora. Os humores da Fada permitem adaptar dano e controle ao encontro, e o upcast automático do Bruxo melhora o espírito.","nivelLabel":"3º nível","funcoes":["Dano","Utilidade"]},{"id":"MAG-0051","nomePt":"Invocar Mortos-Vivos","nomeEn":"Summon undead","nivel":3,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Necromancia","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"27 m (90 ft)","duracao":"Concentração, até 1 hora","componentes":"V, S, M","dano":"Varia conforme a forma escolhida e o nível da magia","material":"Crânio dourado de 300+ PO · não consumido","escalonamento":"O nível do espaço usado define o nível da magia no bloco do Espírito Morto-vivo","funcao1":"Dano","funcao2":"Controle","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Os espaços crescentes de Magia de Pacto fortalecem automaticamente o bloco do espírito. As formas Fantasmagórica, Pútrida e Esquelética permitem adaptar o aliado a mobilidade, combate próximo ou ataque à distância, dando ao Bruxo uma ferramenta sustentada e flexível.","tradeoffs":"Exige Concentração por até 1 hora e um componente de 300+ PO, não consumido. A invocação ocupa sua principal Concentração e desaparece se ela for perdida, competindo com as melhores opções de controle de campo do Bruxo.","melhorQuando":"Combates prolongados ou sequência de encontros em que um segundo corpo no campo, com forma escolhida para o matchup, consegue gerar valor por várias rodadas e aproveitar espaços de Magia de Pacto mais altos.","perdeValor":"Perde valor quando o combate exige dano explosivo imediato, quando sua Concentração precisa sustentar controle mais importante ou quando o espírito não consegue permanecer ativo por várias rodadas.","obs2024":"2024: Ação, 90 pés, Concentração até 1 hora. Invoca um Espírito Morto-vivo e escolhe forma Ghostly, Putrid ou Skeletal, que altera o bloco. Age logo após você na mesma Iniciativa e obedece comandos verbais sem Ação. Exige crânio dourado de 300+ PO, não indicado como consumido. O nível do espaço usado define o nível da magia no bloco.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Invoca um espírito morto-vivo em uma de três formas, cada uma com capacidades próprias, que age logo após você e obedece a seus comandos por até 1 hora.","notas":"Invocação adaptável para combate prolongado: Ghostly, Putrid e Skeletal oferecem perfis diferentes de mobilidade, pressão corpo a corpo e ataque à distância enquanto os espaços do Bruxo fortalecem o espírito.","nivelLabel":"3º nível","funcoes":["Dano","Controle"]},{"id":"MAG-0052","nomePt":"Línguas","nomeEn":"Tongues","nivel":3,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Adivinhação","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"Toque","duracao":"1 hora","componentes":"V, M","dano":"—","material":"Miniatura de zigurate · sem custo indicado · não consumida","escalonamento":"Não escala","funcao1":"Social","funcao2":"Utilidade","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Carisma alto e proficiências sociais transformam o Bruxo em intermediário universal; ganha valor em campanhas diplomáticas, viagens planares e cenas em que a barreira linguística impede Persuasão, Enganação ou negociação.","tradeoffs":"Não exige Concentração, mas usa um espaço de 3º nível para uma função inteiramente contextual e não melhora com espaços superiores. Atua sobre linguagem falada ou sinalizada, não substituindo ferramentas para compreender escrita.","melhorQuando":"Negociação com criaturas que não compartilham idioma, diplomacia planar, interrogatório ou qualquer cena em que comunicação bidirecional por uma hora destrave uma solução que Carisma sozinho não alcançaria.","perdeValor":"Perde prioridade quando o grupo já possui idiomas suficientes, tradução por outra fonte ou quando a campanha raramente coloca comunicação como obstáculo real.","obs2024":"2024: Ação, Toque, duração 1 hora. O alvo entende qualquer idioma falado ou sinalizado que ouça ou veja; quando fala ou sinaliza, qualquer criatura que conheça ao menos um idioma pode entendê-lo se conseguir ouvir ou ver a comunicação.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Faz uma criatura compreender qualquer idioma falado ou sinalizado e permite que outras criaturas que conheçam ao menos um idioma entendam sua comunicação.","notas":"Comunicação universal por 1 hora para fala e sinais. Resolve encontros diplomáticos e interrogatórios específicos, mas é difícil justificar como escolha recorrente quando idiomas raramente bloqueiam a aventura.","nivelLabel":"3º nível","funcoes":["Social","Utilidade"]},{"id":"MAG-0053","nomePt":"Toque Vampírico","nomeEn":"Vampiric touch","nivel":3,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Necromancia","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"Pessoal · alcance corpo a corpo","duracao":"Concentração, até 1 minuto","componentes":"V, S","dano":"3d6 necrótico; recupera PV iguais à metade do dano","material":"—","escalonamento":"+1d6 por nível de espaço acima do 3º","funcao1":"Dano","funcao2":"Defesa","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Pacto da Lâmina (Pact of the Blade), Armadura de Agathys (Armor of Agathys) e builds que já operam no corpo a corpo podem usar a cura recorrente para sustentar presença na linha de frente.","tradeoffs":"Exige Concentração, alcance corpo a corpo e sua Ação a cada rodada para repetir o ataque. O dano é baixo em comparação com Rajada Mística (Eldritch Blast) bem apoiada por Invocações, e a cura só recupera metade do dano necrótico efetivamente causado.","melhorQuando":"Bruxo corpo a corpo já ferido enfrentando inimigos acessíveis e sem resistência relevante a necrótico, quando sobreviver por cura recorrente importa mais que maximizar dano ou manter outro efeito de Concentração.","perdeValor":"Perde prioridade quando a build prefere distância, quando o alvo é difícil de manter corpo a corpo, resiste a necrótico ou quando sua Concentração e Ação valem mais em outro efeito.","obs2024":"2024: Ação, Pessoal, Concentração até 1 minuto. Faz ataque mágico corpo a corpo; no acerto causa 3d6 necrótico e cura metade do dano necrótico causado. Em turnos seguintes, pode repetir o ataque com Ação Mágica. Upcast: +1d6 por nível de espaço acima do 3º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Imbui sua mão com energia necrótica para realizar ataques mágicos corpo a corpo repetidos; cada acerto causa dano necrótico e cura você em metade do dano causado.","notas":"Sustento corpo a corpo que converte dano necrótico em cura. Pode manter um Bruxo ferido em pé, mas exige Concentração e sua Ação rodada após rodada para produzir valor.","nivelLabel":"3º nível","funcoes":["Dano","Defesa"]},{"id":"MAG-0054","nomePt":"Rebote","nomeEn":"Backlash","nivel":4,"grupo":"Magia de Pacto","fonte":"Heroes of Faerûn (HoF)","tagFonte":"HoF","escola":"Abjuração","concentracao":"Não","ritual":"Não","conjuracao":"Reação ao sofrer dano","alcance":"18 m (60 ft)","duracao":"Instantânea","componentes":"V","dano":"Reduz 4d6 + modificador de conjuração; até 4d6 força ao agressor, metade no sucesso","material":"—","escalonamento":"+1d6 na redução e no dano de força por nível de espaço acima do 4º","funcao1":"Defesa","funcao2":"Dano","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Pacto da Lâmina (Pact of the Blade), Armadura de Agathys (Armor of Agathys) e builds expostas a dano aproveitam a combinação de mitigação imediata com retaliação sem gastar Concentração.","tradeoffs":"Usa a Reação e um espaço de 4º nível para responder a um único evento de dano. A redução é forte, mas a retaliação exige que a fonte seja uma criatura a até 60 pés e ainda permite salvaguarda de Constituição; também compete com outras Reações importantes.","melhorQuando":"Quando um golpe, crítico ou efeito de dano relevante ameaça derrubar o Bruxo e a fonte está a até 60 pés, permitindo reduzir o dano e retaliar no mesmo recurso.","perdeValor":"Perde prioridade quando o dano recebido é pequeno, o agressor está fora do alcance, sua Reação precisa ficar livre ou quando gastar um espaço de 4º nível não evita uma consequência realmente importante.","obs2024":"HoF, regras 2024: Reação ao sofrer dano, 60 pés, Instantânea. Reduz o dano recebido em 4d6 + modificador da habilidade de conjuração. Se a fonte for uma criatura no alcance, ela faz salvaguarda de Constituição e sofre 4d6 de Força em falha ou metade no sucesso. Upcast: redução e dano aumentam em 1d6 por nível acima do 4º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/frhof","oQueFaz":"Quando você sofre dano, usa sua Reação para reduzir esse dano e, se a fonte for uma criatura próxima, pode atingi-la com uma onda de força.","notas":"Reação defensiva que reduz um pico de dano e ainda pode devolvê-lo como dano de Força. É uma opção HoF interessante para Bruxos expostos, especialmente quando sobreviver ao golpe importa mais que guardar o espaço.","nivelLabel":"4º nível","funcoes":["Defesa","Dano"]},{"id":"MAG-0055","nomePt":"Banimento","nomeEn":"Banishment","nivel":4,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Abjuração","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"9 m (30 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S, M","dano":"—","material":"Pentáculo · sem custo indicado · não consumido","escalonamento":"+1 alvo por nível de espaço acima do 4º","funcao1":"Controle","funcao2":"Defesa","prioridadeN":4,"classificacao":"ESSENCIAL","sinergias":"Estilhaço Mental (Mind Sliver), Perdição (Bane) e outros efeitos que prejudiquem salvaguardas ajudam no único teste inicial. A progressão automática da Magia de Pacto permite atingir dois alvos quando o Bruxo chega aos espaços de 5º nível.","tradeoffs":"Exige Concentração e salvaguarda de Carisma. Se a Concentração for perdida, o alvo retorna cedo; contra criaturas que não sejam Aberrações, Celestiais, Elementais, Fadas ou Ínferos, o efeito é apenas temporário mesmo quando dura o minuto completo.","melhorQuando":"Contra um ou dois inimigos perigosos que precisam sair do combate imediatamente enquanto o grupo resolve o restante do encontro, sobretudo alvos com Carisma baixo.","perdeValor":"Cai contra criaturas com Carisma alto, quando sua Concentração é facilmente quebrada ou quando remover temporariamente um alvo não muda a economia do encontro.","obs2024":"2024: Ação, 30 pés, Concentração até 1 minuto. Em falha na salvaguarda de Carisma, o alvo vai para um semiplano inofensivo e fica Incapacitado. Aberrações, Celestiais, Elementais, Fadas e Ínferos não retornam se a magia durar o minuto completo; outros alvos retornam quando termina. Upcast: +1 alvo por nível acima do 4º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Tenta expulsar uma criatura para um semiplano, deixando-a Incapacitada; certos tipos extraplanares podem ser removidos permanentemente se a Concentração durar o minuto completo.","notas":"Controle direto para retirar um inimigo perigoso da luta sem salvaguardas repetidas. No 5º nível de espaço do Bruxo, já pode atingir dois alvos e transformar um combate difícil em dois problemas menores.","nivelLabel":"4º nível","funcoes":["Controle","Defesa"]},{"id":"MAG-0056","nomePt":"Definhar","nomeEn":"Blight","nivel":4,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Necromancia","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"9 m (30 ft)","duracao":"Instantânea","componentes":"V, S","dano":"8d8 necrótico; metade no sucesso; Planta falha automaticamente","material":"—","escalonamento":"+1d8 por nível de espaço acima do 4º","funcao1":"Dano","funcao2":null,"prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Funciona como explosão de dano sem Concentração, permitindo manter Bruxaria (Hex), Fome de Hadar (Hunger of Hadar) ou outra magia sustentada. Contra criaturas Planta, a falha automática na salvaguarda torna o resultado especialmente confiável.","tradeoffs":"É dano de alvo único usando um espaço valioso de Magia de Pacto e pede salvaguarda de Constituição, frequentemente forte em monstros robustos. Mesmo com metade do dano no sucesso, compete com opções de controle e invocação que podem gerar valor por várias rodadas.","melhorQuando":"Quando é necessário causar dano imediato sem quebrar Concentração, especialmente contra uma criatura Planta ou um alvo já vulnerável a dano necrótico.","perdeValor":"Perde prioridade quando o encontro pede controle ou dano em área, quando o alvo tem Constituição alta ou resistência a necrótico, ou quando outra magia gera valor por várias rodadas.","obs2024":"2024: Ação, 30 pés, Instantânea. Uma criatura faz salvaguarda de Constituição: 8d8 necrótico em falha ou metade no sucesso. Criaturas Planta falham automaticamente. Também pode fazer uma planta não mágica que não seja criatura murchar e morrer. Upcast: +1d8 por nível acima do 4º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Drena a vitalidade de uma criatura com energia necrótica, causando alto dano em falha na salvaguarda; criaturas Planta falham automaticamente.","notas":"Explosão de dano necrótico sem Concentração. É simples e confiável contra Plantas, mas normalmente compete com controles e invocações que conseguem gerar mais valor ao longo de várias rodadas.","nivelLabel":"4º nível","funcoes":["Dano"]},{"id":"MAG-0057","nomePt":"Enfeitiçar Monstro","nomeEn":"Charm monster","nivel":4,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"9 m (30 ft)","duracao":"1 hora","componentes":"V, S","dano":"—","material":"—","escalonamento":"+1 alvo por nível de espaço acima do 4º","funcao1":"Social","funcao2":"Controle","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Carisma alto, proficiências sociais, Máscara das Muitas Faces (Mask of Many Faces) e campanhas de intriga ajudam a transformar a condição Amigável em vantagem prática. Não exigir Concentração permite combiná-la com outras magias sustentadas.","tradeoffs":"O alvo tem Vantagem na salvaguarda se já estiver lutando contra você ou seus aliados, o efeito termina se você ou seus aliados causarem dano e a criatura sabe que foi enfeitiçada quando a magia acaba. Portanto, é mais forte antes do combate do que durante uma luta aberta.","melhorQuando":"Negociação, infiltração ou preparação contra uma criatura não Humanoide quando torná-la Amigável por uma hora pode evitar combate, obter acesso ou criar uma janela de cooperação.","perdeValor":"Cai contra imunidade a Enfeitiçado (Charmed), em combate direto onde o dano encerra o efeito ou quando a campanha oferece poucas oportunidades de negociação antes da luta.","obs2024":"2024: Ação, 30 pés, duração 1 hora. Uma criatura faz salvaguarda de Sabedoria, com Vantagem se estiver lutando contra você ou seus aliados. Em falha fica Enfeitiçada e Amigável até a magia acabar ou você/seus aliados causarem dano. Ao terminar, sabe que foi enfeitiçada. Upcast: +1 criatura por nível acima do 4º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Tenta Enfeitiçar uma criatura de qualquer tipo por até 1 hora, tornando-a Enfeitiçada e Amigável em caso de falha; ela percebe o encantamento quando o efeito termina.","notas":"Ferramenta social ampla que funciona contra qualquer criatura, não apenas Humanoides. Pode evitar um combate ou destravar negociação, mas seu valor depende muito da campanha e do momento anterior à luta.","nivelLabel":"4º nível","funcoes":["Social","Controle"]},{"id":"MAG-0058","nomePt":"Porta Dimensional","nomeEn":"Dimension door","nivel":4,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"152 m (500 ft)","duracao":"Instantânea","componentes":"V","dano":"4d6 força se o destino estiver ocupado; o teleporte falha","material":"—","escalonamento":"Não escala","funcao1":"Exploração","funcao2":null,"prioridadeN":4,"classificacao":"ESSENCIAL","sinergias":"Pacto da Lâmina (Pact of the Blade), resgate de aliados e builds de controle aproveitam o teleporte para sair de uma posição ruim sem encerrar a Concentração já ativa. Pode levar uma criatura voluntária próxima junto com o Bruxo.","tradeoffs":"Gasta um espaço de 4º ou 5º nível e não recebe benefício de upcast. Se o destino estiver ocupado ou completamente preenchido por objetos, o teleporte falha e os viajantes sofrem 4d6 de Força.","melhorQuando":"Fuga de emergência, retirada de um aliado, atravessar barreiras ou reposicionamento de até 500 pés quando deslocamento normal ou Passo Nebuloso (Misty Step) não resolvem.","perdeValor":"Só perde prioridade quando outra fonte de teleporte já cobre a mesma distância, quando o destino arriscado torna a falha perigosa ou quando mobilidade longa simplesmente não é necessária.","obs2024":"2024: Ação, 500 pés, Instantânea. Teleporta você para um local visível, visualizado ou descrito por distância e direção; pode levar uma criatura voluntária a até 5 pés. Se o destino estiver ocupado ou completamente preenchido, o teleporte falha e cada viajante sofre 4d6 de Força. Sem upcast.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Teleporta você e, opcionalmente, uma criatura voluntária próxima para um ponto a até 500 pés que você possa ver, visualizar ou descrever por distância e direção.","notas":"Teleporte de longo alcance que resolve fuga, resgate e travessia de barreiras sem exigir Concentração. É uma das ferramentas de mobilidade mais versáteis disponíveis ao Bruxo.","nivelLabel":"4º nível","funcoes":["Exploração"]},{"id":"MAG-0059","nomePt":"Maré da Perdição","nomeEn":"Doomtide","nivel":4,"grupo":"Magia de Pacto","fonte":"Heroes of Faerûn (HoF)","tagFonte":"HoF","escola":"Conjuração","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"36 m (120 ft) · esfera de raio 6 m (20 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S, M","dano":"5d6 psíquico; metade no sucesso","material":"fuligem e uma enguia seca · não consumido","escalonamento":"Sem escalonamento por nível de espaço","funcao1":"Controle","funcao2":"Dano","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Visão Diabólica (Devil’s Sight) ajuda o Bruxo a operar dentro da Escuridão mágica, enquanto Rajada Repulsiva (Repelling Blast), empurrões e bloqueio de rotas podem aumentar a chance de inimigos permanecerem ou voltarem para a esfera. A penalidade de 1d6 em salvaguardas prepara controles do grupo.","tradeoffs":"A esfera se move automaticamente 10 pés para longe de você no início dos seus turnos, então manter inimigos nela exige planejamento. Usa Concentração, pode afetar aliados e vento forte pode dispersar a névoa; o benefício repetido depende bastante de posicionamento.","melhorQuando":"Combates em corredores, ruas ou áreas onde o movimento previsível da esfera atravesse vários inimigos e o grupo consiga capitalizar a Escuridão, o dano psíquico recorrente e a penalidade em salvaguardas.","perdeValor":"Perde valor quando o grupo precisa de linhas de visão limpas, quando os inimigos conseguem sair facilmente da esfera, quando vento forte dispersa a névoa ou quando o movimento automático atrapalha o plano.","obs2024":"HoF, regras 2024: Ação, 120 pés, Esfera de 20 pés, Concentração até 1 minuto. A névoa é Escuridão mágica. Criaturas afetadas fazem salvaguarda de Sabedoria: 5d6 psíquico e -1d6 nas salvaguardas até o fim do próximo turno em falha; metade do dano no sucesso. A esfera move 10 pés para longe de você no início dos seus turnos. Vento forte dispersa a névoa. Possui variante de Circle Spell.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/frhof","oQueFaz":"Cria uma esfera móvel de escuridão mágica que causa dano psíquico e penaliza salvaguardas dos alvos que falharem, deslocando-se automaticamente a cada turno.","notas":"Controle HoF agressivo que mistura Escuridão mágica, dano psíquico recorrente e penalidade em salvaguardas. Fica especialmente forte quando o grupo consegue prever e controlar o deslocamento da esfera.","nivelLabel":"4º nível","funcoes":["Controle","Dano"]},{"id":"MAG-0060","nomePt":"Terreno Alucinatório","nomeEn":"Hallucinatory terrain","nivel":4,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Ilusão","concentracao":"Não","ritual":"Não","conjuracao":"10 minutos","alcance":"91 m (300 ft) · cubo de 46 m (150 ft)","duracao":"24 horas","componentes":"V, S, M","dano":"—","material":"Um cogumelo · sem custo indicado · não consumido","escalonamento":"Não escala","funcao1":"Exploração","funcao2":"Controle","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Ilusão Menor (Minor Illusion), Imagem Maior (Major Image), Máscara das Muitas Faces (Mask of Many Faces) e estratégias de engano podem tornar a alteração do ambiente mais convincente e criar rotas falsas, coberturas aparentes ou distrações de larga escala.","tradeoffs":"Tempo de conjuração de 10 minutos impede uso reativo em combate, e apenas terreno natural é alterado visualmente, sonoramente e pelo cheiro; estruturas, equipamentos e criaturas permanecem iguais. O tato também não muda, podendo revelar rapidamente a ilusão.","melhorQuando":"Preparação de emboscada, defesa de território, esconder uma rota ou transformar visualmente uma área natural de 150 pés antes de inimigos chegarem.","perdeValor":"Quase não serve em combate iniciado de surpresa; perde prioridade em campanhas com pouca preparação, poucos terrenos naturais relevantes ou inimigos que podem investigar a ilusão com facilidade.","obs2024":"2024: 10 minutos, 300 pés, Cubo de 150 pés, duração 24 horas, sem Concentração. Faz terreno natural parecer, soar e cheirar como outro terreno natural; estruturas, equipamentos e criaturas não mudam. Características táteis permanecem reais. Uma criatura pode usar Estudar com Inteligência (Investigação) contra a CD da magia para desacreditar a ilusão.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Transforma a aparência, os sons e os cheiros de uma grande área de terreno natural para fazê-la parecer outro tipo de terreno, sem alterar suas características físicas.","notas":"Ilusão de larga escala para preparação de terreno, emboscadas e engano ambiental. Não é uma magia de combate reativo, mas pode alterar completamente como inimigos percebem uma área antes do confronto.","nivelLabel":"4º nível","funcoes":["Exploração","Controle"]},{"id":"MAG-0061","nomePt":"Invocar Aberração","nomeEn":"Summon aberration","nivel":4,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"27 m (90 ft)","duracao":"Concentração, até 1 hora","componentes":"V, S, M","dano":"Varia conforme a forma escolhida e o nível da magia","material":"Tentáculo em conserva e olho em frasco de platina de 400+ PO · não consumidos","escalonamento":"O nível do espaço usado define o nível da magia no bloco do Espírito Aberrante","funcao1":"Dano","funcao2":"Controle","prioridadeN":4,"classificacao":"ESSENCIAL","sinergias":"Grande Antigo (Great Old One) tem sinergia excepcional: no nível 14, Criar Lacaio (Create Thrall) pode remover a Concentração por 1 minuto, conceder PV temporários ao espírito e aumentar o dano contra alvos de Bruxaria (Hex). Mesmo fora dessa subclasse, o upcast automático da Magia de Pacto fortalece o bloco.","tradeoffs":"Exige Concentração por até 1 hora e um componente de 400+ PO, embora não seja consumido. Enquanto a invocação estiver ativa, o Bruxo abre mão de Fome de Hadar (Hunger of Hadar), Banimento (Banishment) e outros controles de Concentração.","melhorQuando":"Combates prolongados ou sequência de encontros em que um aliado Aberração pode gerar valor por várias rodadas, escolhendo Beholderkin, Mind Flayer ou Slaad conforme distância, pressão mental ou durabilidade necessárias.","perdeValor":"Perde prioridade quando a Concentração precisa sustentar um controle de área mais decisivo, quando o espírito não sobrevive bem ao encontro ou quando a luta é curta demais para aproveitar sua duração.","obs2024":"2024: Ação, 90 pés, Concentração até 1 hora. Invoca um Espírito Aberrante e escolhe Beholderkin, Mind Flayer ou Slaad; a forma altera detalhes do bloco. Age logo após você na mesma Iniciativa e obedece comandos verbais sem Ação. Exige tentáculo em conserva e olho em frasco com platina de 400+ PO. Upcast usa o nível do espaço no bloco do espírito.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Invoca um espírito aberrante em uma das formas disponíveis, cada uma com capacidades próprias, que luta ao seu lado e obedece a comandos verbais por até 1 hora.","notas":"Invocação duradoura com três perfis táticos diferentes. Beholderkin, Mind Flayer e Slaad permitem adaptar alcance, pressão e durabilidade, e os espaços maiores do Bruxo fortalecem o espírito automaticamente.","nivelLabel":"4º nível","funcoes":["Dano","Controle"]},{"id":"MAG-0062","nomePt":"Contatar Outro Plano","nomeEn":"Contact other plane","nivel":5,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Adivinhação","concentracao":"Não","ritual":"Sim","conjuracao":"1 minuto ou Ritual","alcance":"Pessoal","duracao":"1 minuto","componentes":"V","dano":"6d6 psíquico se falhar na salvaguarda de Inteligência","material":"—","escalonamento":"Não escala","funcao1":"Exploração","funcao2":null,"prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"A característica Contatar Patrono (Contact Patron), obtida pelo Bruxo no nível 9, mantém esta magia sempre preparada, permite conjurá-la uma vez por Descanso Longo sem gastar espaço e faz o Bruxo obter sucesso automático na salvaguarda ao contatar seu patrono.","tradeoffs":"Fora do uso gratuito de Contatar Patrono (Contact Patron), a magia exige uma salvaguarda de Inteligência CD 15; falhar causa 6d6 psíquico e Incapacitado até um Descanso Longo. As respostas também são curtas e dependem do conhecimento da entidade e da adjudicação do Mestre.","melhorQuando":"Antes de uma decisão importante, investigação ou confronto em que até cinco respostas do patrono possam revelar risco, direção, identidade ou consequência sem consumir um espaço de Magia de Pacto.","perdeValor":"Perde prioridade quando as respostas não mudam a decisão do grupo, quando o Mestre só pode fornecer informação pouco útil ou quando a campanha oferece poucas situações em que cinco respostas justificam a escolha.","obs2024":"2024: 1 minuto ou Ritual, Pessoal, duração 1 minuto. Após salvaguarda de Inteligência CD 15, em sucesso você faz até cinco perguntas a uma entidade extraplanar e recebe respostas curtas; em falha sofre 6d6 psíquico e fica Incapacitado até terminar um Descanso Longo. Contatar Patrono (Contact Patron), nível 9 de Bruxo, mantém a magia sempre preparada, permite uma conjuração gratuita por Descanso Longo e dá sucesso automático na salvaguarda ao contatar o patrono.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Faz até cinco perguntas a uma entidade extraplanar e recebe respostas curtas; uma falha na salvaguarda de Inteligência causa dano psíquico e Incapacita você até um Descanso Longo.","notas":"Na prática, funciona como recurso da classe: a partir do nível 9, Contatar Patrono (Contact Patron) mantém a magia preparada, oferece uma conjuração gratuita por Descanso Longo e elimina o risco da salvaguarda ao falar com seu patrono.","nivelLabel":"5º nível","funcoes":["Exploração"]},{"id":"MAG-0063","nomePt":"Sonho","nomeEn":"Dream","nivel":5,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Ilusão","concentracao":"Não","ritual":"Não","conjuracao":"1 minuto","alcance":"Especial","duracao":"8 horas","componentes":"V, S, M","dano":"3d6 psíquico ao despertar se o alvo falhar na salvaguarda","material":"Punhado de areia · sem custo · não consumido","escalonamento":"Não escala","funcao1":"Social","funcao2":"Exploração","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Carisma alto, campanhas de intriga e alvos conhecidos em qualquer distância no mesmo plano tornam a magia uma ferramenta de comunicação e pressão remota; pode transmitir informação sem depender de uma rota física até o alvo.","tradeoffs":"Tempo de conjuração de 1 minuto e efeito fortemente dependente de narrativa tornam o espaço de 5º nível caro. A versão hostil exige salvaguarda de Sabedoria e causa apenas 3d6 psíquico, de modo que o principal valor está na comunicação, não no dano.","melhorQuando":"Comunicação secreta de longa distância, manipulação narrativa ou assédio de um alvo conhecido no mesmo plano quando contato físico, Mensagem (Message) ou envio convencional não são viáveis.","perdeValor":"Perde valor em campanhas focadas em combate, quando o alvo raramente dorme ou não está no mesmo plano, e quando comunicação de longa distância não altera o rumo da aventura.","obs2024":"2024: 1 minuto, 10 pés, duração Especial. Você ou uma criatura voluntária entra em transe como mensageiro dos sonhos de uma criatura conhecida no mesmo plano. Se o alvo dormir, é possível conversar e moldar o sonho; o alvo recorda o sonho ao acordar. A versão aterrorizante transmite até 10 palavras e exige salvaguarda de Sabedoria; em falha o alvo não recebe benefício do descanso e sofre 3d6 psíquico ao acordar.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Entra nos sonhos de uma criatura adormecida para conversar e moldar o sonho; opcionalmente, pode transformar a mensagem em pesadelo que prejudica o descanso e causa dano psíquico.","notas":"Comunicação remota e discreta com uma criatura conhecida no mesmo plano. É excelente para intriga e pressão narrativa, mas difícil de justificar como escolha recorrente quando comunicação por sonhos raramente resolve problemas da campanha.","nivelLabel":"5º nível","funcoes":["Social","Exploração"]},{"id":"MAG-0064","nomePt":"Imobilizar Monstro","nomeEn":"Hold monster","nivel":5,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"27 m (90 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S, M","dano":"—","material":"Pedaço reto de ferro · sem custo · não consumido","escalonamento":"+1 criatura por nível de espaço acima do 5º","funcao1":"Controle","funcao2":null,"prioridadeN":4,"classificacao":"ESSENCIAL","sinergias":"Estilhaço Mental (Mind Sliver), Perdição (Bane) e aliados corpo a corpo exploram muito bem a condição Paralisado. Ao contrário de Imobilizar Pessoa (Hold Person), pode afetar qualquer criatura válida, inclusive Mortos-vivos na versão 2024.","tradeoffs":"Exige Concentração, depende de salvaguarda de Sabedoria e o alvo repete a salvaguarda no fim de cada turno. Um Bruxo puro não possui espaços de Magia de Pacto acima do 5º nível, então normalmente não aproveita o upcast para atingir alvos adicionais.","melhorQuando":"Contra uma criatura perigosa que precisa ser neutralizada imediatamente e que o grupo consegue pressionar com ataques corpo a corpo enquanto estiver Paralisada.","perdeValor":"Perde valor contra inimigos com Sabedoria alta, imunidade a Paralisado, encontros com muitos alvos ou quando manter Concentração em um único alvo é um custo alto demais.","obs2024":"2024: Ação, 90 pés, Concentração até 1 minuto. Uma criatura faz salvaguarda de Sabedoria; em falha fica Paralisada e repete a salvaguarda ao fim de cada turno. A restrição antiga contra Mortos-vivos foi removida. Upcast adiciona um alvo por nível acima do 5º, embora a Magia de Pacto do Bruxo puro termine no 5º nível.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Paralisa uma criatura de qualquer tipo que falhe na salvaguarda de Sabedoria, permitindo novas salvaguardas ao fim de cada turno para encerrar o efeito.","notas":"Controle de alvo único de alto impacto: Paralisado pode apagar o turno de uma criatura perigosa e abrir uma janela brutal para ataques corpo a corpo. Em 2024, também funciona contra Mortos-vivos.","nivelLabel":"5º nível","funcoes":["Controle"]},{"id":"MAG-0065","nomePt":"Tempestade de Radiância de Jallarzi","nomeEn":"Jallarzi’s storm of radiance","nivel":5,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Evocação","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"36 m (120 ft) · cilindro de raio 3 m (10 ft) e altura 12 m (40 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S, M","dano":"2d10 radiante + 2d10 trovão; metade no sucesso","material":"Pitada de fósforo · sem custo · não consumida","escalonamento":"+1d10 radiante e +1d10 trovão por nível de espaço acima do 5º","funcao1":"Dano","funcao2":"Controle","prioridadeN":4,"classificacao":"ESSENCIAL","sinergias":"Rajada Repulsiva (Repelling Blast), propriedades de Empurrão (Push) e outros efeitos de movimento forçado podem devolver inimigos à área e gerar novos gatilhos de dano em turnos diferentes. A Cegueira automática também melhora os ataques dos aliados contra criaturas dentro da tempestade.","tradeoffs":"Exige Concentração e ocupa um Cilindro relativamente estreito de 10 pés de raio; inimigos móveis podem sair da área. A tempestade também afeta aliados dentro dela, impondo Cegueira, Surdez e bloqueando magias com componente Verbal.","melhorQuando":"Corredores, áreas verticais, grupos compactos ou conjuradores inimigos que precisam ser privados de visão e de componentes Verbais enquanto o grupo os empurra de volta para a zona.","perdeValor":"Perde valor em mapas muito abertos, contra inimigos extremamente móveis ou quando aliados precisam permanecer dentro da área e seriam prejudicados pela Cegueira, Surdez e bloqueio verbal.","obs2024":"2024: Ação, 120 pés, Cilindro de 10 pés de raio e 40 pés de altura, Concentração até 1 minuto. Criaturas na área ficam Cegas e Surdas e não podem conjurar magias com componente Verbal. Ao surgir, entrar pela primeira vez em um turno ou terminar o turno na área, a criatura faz salvaguarda de Constituição: 2d10 radiante + 2d10 trovejante em falha, metade no sucesso; no máximo uma salvaguarda por turno.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Cria uma tempestade cilíndrica de luz e trovões que Cega e Ensurdece criaturas na área, impede magias com componente Verbal e causa dano radiante e trovejante.","notas":"Zona anti-conjurador que combina Cegueira, Surdez, bloqueio de componentes Verbais e dano repetido. Fica muito forte em corredores, espaços verticais e grupos que conseguem empurrar inimigos de volta para a área.","nivelLabel":"5º nível","funcoes":["Dano","Controle"]},{"id":"MAG-0066","nomePt":"Despistar","nomeEn":"Mislead","nivel":5,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Ilusão","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"Pessoal","duracao":"Concentração, até 1 hora","componentes":"S","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Exploração","funcao2":"Defesa","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Máscara das Muitas Faces (Mask of Many Faces), infiltração e reconhecimento aproveitam o duplo ilusório para criar distração enquanto o Bruxo se torna Invisível; enxergar e ouvir pelos sentidos do duplo permite reconhecimento remoto sem expor o corpo real.","tradeoffs":"Exige Concentração e uma Ação para começar. A Invisibilidade termina ao atacar, causar dano ou conjurar magia, e mover/controlar o duplo exige Ação Mágica; para simples fuga ou infiltração, Invisibilidade (Invisibility) e Porta Dimensional (Dimension Door) frequentemente custam menos oportunidade.","melhorQuando":"Infiltração ou fuga em que uma distração móvel e invulnerável precisa atrair atenção enquanto o Bruxo se afasta Invisível ou observa o ambiente pelos sentidos do duplo.","perdeValor":"Perde prioridade em combates diretos onde você precisa usar sua Ação para causar impacto imediato, ou quando Invisibilidade (Invisibility) e Porta Dimensional (Dimension Door) já resolvem fuga e infiltração.","obs2024":"2024: Ação, Pessoal, Concentração até 1 hora. Você fica Invisível e cria um duplo ilusório no seu espaço. A Invisibilidade termina imediatamente após fazer uma jogada de ataque, causar dano ou conjurar magia, mas o duplo permanece enquanto a magia durar. Com Ação Mágica, o duplo move até o dobro do seu Deslocamento e pode gesticular, falar e agir; você pode ver e ouvir pelos sentidos dele.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Torna você Invisível e cria um duplo ilusório que pode se mover, falar e transmitir visão e audição; sua Invisibilidade pode terminar enquanto o duplo permanece.","notas":"Mistura Invisibilidade, distração e reconhecimento remoto em um único efeito. É versátil para infiltração planejada, mas cara demais quando o objetivo é apenas fugir ou se esconder.","nivelLabel":"5º nível","funcoes":["Exploração","Defesa"]},{"id":"MAG-0067","nomePt":"Vínculo Planar","nomeEn":"Planar binding","nivel":5,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Abjuração","concentracao":"Não","ritual":"Não","conjuracao":"1 hora","alcance":"18 m (60 ft)","duracao":"24 horas","componentes":"V, S, M","dano":"—","material":"Joia de 1.000+ PO · consumida","escalonamento":"6º: 10 dias; 7º: 30 dias; 8º: 180 dias; 9º: 366 dias","funcao1":"Utilidade","funcao2":"Controle","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Círculo Mágico (Magic Circle) invertido é a preparação clássica para manter uma criatura válida dentro do alcance durante a hora de conjuração. Criaturas conjuradas por outras magias têm a duração estendida para acompanhar Vinculação Planar se a vinculação funcionar.","tradeoffs":"Exige 1 hora de conjuração, uma criatura Celestial, Elemental, Fada ou Ínfero mantida a até 60 pés durante todo o processo e uma joia de 1.000+ PO consumida. Em um Bruxo puro, a Magia de Pacto não sobe além do 5º nível, então a duração típica permanece 24 horas.","melhorQuando":"Campanha com preparação, recursos e acesso a uma entidade extraplanar poderosa quando transformá-la em aliado por 24 horas justifica o custo material e a logística de contenção.","perdeValor":"Perde prioridade em campanhas de aventura rápida, sem preparação, sem acesso a uma criatura adequada ou quando o custo de 1.000+ PO e uma hora de conjuração não compensam 24 horas de serviço.","obs2024":"2024: 1 hora, 60 pés, duração 24 horas. Vincula um Celestial, Elemental, Fada ou Ínfero que permaneça no alcance durante toda a conjuração. Ao final, salvaguarda de Carisma; em falha, serve ao conjurador pela duração. Se foi invocado/criado por outra magia, a duração dessa magia é estendida para acompanhar esta. Consome joia de 1.000+ PO. Upcast aumenta a duração, mas o Bruxo puro não possui espaços de Magia de Pacto acima do 5º.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Prende um Celestial, Elemental, Fada ou Ínfero ao seu serviço por 24 horas se falhar na salvaguarda, podendo estender a duração de uma magia que o tenha invocado.","notas":"Magia de preparação com teto altíssimo: transforma uma criatura extraplanar em serva por 24 horas. O problema é todo o processo necessário para conter o alvo, conjurar por 1 hora e pagar o componente consumido.","nivelLabel":"5º nível","funcoes":["Utilidade","Controle"]},{"id":"MAG-0068","nomePt":"Vidência","nomeEn":"Scrying","nivel":5,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Adivinhação","concentracao":"Sim","ritual":"Não","conjuracao":"10 minutos","alcance":"Pessoal","duracao":"Concentração, até 10 minutos","componentes":"V, S, M","dano":"—","material":"um foco no valor de 1.000+ PO, como bola de cristal, espelho ou fonte com água · não consumido","escalonamento":"Não escala","funcao1":"Exploração","funcao2":null,"prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Conhecimento prévio, retratos, pertences e partes corporais do alvo reduzem a salvaguarda, recompensando investigação anterior. A recuperação de espaços em Descanso Curto permite tentar a magia em momentos estratégicos sem sacrificar necessariamente recursos do próximo combate.","tradeoffs":"Exige 10 minutos, Concentração e foco de 1.000+ PO. O alvo faz salvaguarda de Sabedoria modificada pelo quanto você o conhece; em sucesso fica imune às suas novas tentativas por 24 horas, o que impede repetição imediata.","melhorQuando":"Antes de uma missão, emboscada ou descanso, quando observar um antagonista, aliado distante ou local conhecido pode revelar posição, companhia, segurança ou preparação sem entrar fisicamente na área.","perdeValor":"Perde prioridade quando a informação obtida não muda a decisão do grupo, quando o alvo tem boa chance de resistir ou quando o foco de 1.000+ PO e o tempo de preparação são barreiras reais.","obs2024":"2024: 10 minutos, Pessoal, Concentração até 10 minutos. Permite ver e ouvir uma criatura no mesmo plano; a salvaguarda de Sabedoria recebe modificadores conforme seu conhecimento e conexões físicas com o alvo. Em sucesso, o alvo não é afetado e não pode ser alvo novamente por você por 24 horas. Em falha, surge um sensor Invisível e intangível a até 10 pés do alvo. Também pode mirar um local que você já viu. Exige foco de 1.000+ PO, não consumido.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Cria um sensor mágico invisível próximo a uma criatura ou local distante, permitindo ver e ouvir através dele enquanto você mantiver Concentração.","notas":"Ferramenta estratégica de informação para observar criaturas ou locais no mesmo plano. O Bruxo aproveita bem a recuperação por Descanso Curto, podendo usar Vidência antes de missões sem necessariamente sacrificar recursos do próximo combate.","nivelLabel":"5º nível","funcoes":["Exploração"]},{"id":"MAG-0069","nomePt":"Estática Sináptica","nomeEn":"Synaptic static","nivel":5,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"36 m (120 ft) · esfera de raio 6 m (20 ft)","duracao":"Instantânea","componentes":"V, S","dano":"8d6 psíquico; metade no sucesso","material":"—","escalonamento":"Não escala","funcao1":"Dano","funcao2":"Controle","prioridadeN":4,"classificacao":"ESSENCIAL","sinergias":"Funciona especialmente bem ao lado de Fome de Hadar (Hunger of Hadar), Banimento (Banishment) ou outra magia de Concentração, porque aplica dano em área e um debuff persistente sem ocupar sua Concentração. O -1d6 em salvaguardas de Constituição também dificulta que conjuradores inimigos mantenham Concentração.","tradeoffs":"Afeta todas as criaturas na esfera, então exige posicionamento cuidadoso para não atingir aliados. O debuff depende de falha na salvaguarda de Inteligência e pode terminar em salvaguardas repetidas ao fim dos turnos; como espaço de 5º nível, também compete com controles extremamente fortes.","melhorQuando":"Grupo de inimigos agrupados, principalmente criaturas com Inteligência baixa ou conjuradores, quando o Bruxo quer causar dano em área e reduzir ataques, testes e salvaguardas de Concentração sem abandonar outra magia sustentada.","perdeValor":"Perde prioridade quando o encontro tem poucos alvos, quando o grupo corre risco de ser atingido pela área ou quando um controle de Concentração produz impacto maior do que dano + debuff.","obs2024":"2024: Ação, 120 pés, Esfera de 20 pés, Instantânea. Salvaguarda de Inteligência: 8d6 psíquico em falha ou metade no sucesso. Em falha, por até 1 minuto o alvo subtrai 1d6 de jogadas de ataque, testes de habilidade e salvaguardas de Constituição para manter Concentração; repete a salvaguarda de Inteligência ao fim de cada turno para encerrar o efeito. Não exige Concentração.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Explode energia psíquica em uma grande área, causando dano e, em falha na salvaguarda, impondo uma penalidade de 1d6 a ataques, testes de habilidade e salvaguardas de Constituição para manter Concentração por até 1 minuto.","notas":"Uma das melhores magias de 5º nível para Bruxo: dano psíquico em área, salvaguarda de Inteligência e debuff persistente sem Concentração, permitindo manter outro controle importante ativo ao mesmo tempo.","nivelLabel":"5º nível","funcoes":["Dano","Controle"]},{"id":"MAG-0070","nomePt":"Círculo de Teletransporte","nomeEn":"Teleportation circle","nivel":5,"grupo":"Magia de Pacto","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Não","ritual":"Não","conjuracao":"1 minuto","alcance":"3 m (10 ft)","duracao":"1 rodada","componentes":"V, M","dano":"—","material":"Tintas raras de 50+ PO · consumidas","escalonamento":"Não escala","funcao1":"Exploração","funcao2":"Utilidade","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Campanhas com rede conhecida de círculos permanentes, Bastions, guildas ou bases recorrentes transformam a magia em infraestrutura de viagem para o grupo inteiro. Aprender novas sequências de sigilos aumenta progressivamente o número de destinos úteis.","tradeoffs":"Tempo de conjuração de 1 minuto, tinta rara de 50+ PO consumida e necessidade de conhecer um círculo permanente no mesmo plano tornam o uso altamente dependente da campanha. Não serve como teleporte livre para qualquer destino e ocupa uma magia preparada de 5º nível.","melhorQuando":"Campanhas de grande escala em que o grupo visita repetidamente cidades, fortalezas ou bases com círculos permanentes conhecidos e precisa eliminar dias ou semanas de viagem.","perdeValor":"Perde valor em campanhas sem círculos permanentes conhecidos, em regiões isoladas ou quando o grupo raramente revisita destinos a ponto de economizar tempo de viagem de forma relevante.","obs2024":"2024: 1 minuto, 10 pés, duração 1 rodada. Desenha um círculo de 5 pés de raio e abre portal até o fim do seu próximo turno para um círculo permanente conhecido no mesmo plano. Ao aprender a magia, você conhece duas sequências de destino no Plano Material determinadas pelo Mestre e pode aprender outras. Consome tintas raras de 50+ PO. Conjurar no mesmo local todos os dias por 365 dias cria um círculo permanente.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Abre por uma rodada um portal para um círculo de teletransporte permanente conhecido no mesmo plano; conjurações repetidas no mesmo lugar podem criar um círculo permanente.","notas":"Infraestrutura de viagem para campanhas de grande escala. Quando o grupo possui destinos recorrentes com círculos permanentes, elimina jornadas inteiras; fora desse tipo de campanha, pode quase nunca justificar a escolha.","nivelLabel":"5º nível","funcoes":["Exploração","Utilidade"]},{"id":"MAG-0071","nomePt":"Portais Arcanos","nomeEn":"Arcane gate","nivel":6,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"150 m (500 ft)","duracao":"Concentração, até 10 minutos","componentes":"V, S","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Exploração","funcao2":"Utilidade","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"O portal pode transportar repetidamente o grupo inteiro por até 10 minutos, permitindo reposicionamento coletivo, retirada e criação de rotas táticas. Funciona melhor quando o Bruxo consegue enxergar um ponto útil a longa distância e o grupo pode explorar várias travessias.","tradeoffs":"Como Arcano Místico (Mystic Arcanum) de 6º nível, compete pela única escolha desse nível e só pode ser usado dessa forma uma vez por Descanso Longo. Exige Concentração, linha de visão para os dois espaços e terreno desocupado; para transportar apenas uma ou duas criaturas, Porta Dimensional (Dimension Door) costuma ser mais simples.","melhorQuando":"Retirada ou avanço de um grupo inteiro, travessia repetida de uma grande distância visível ou combate preparado em que manter dois pontos do mapa conectados por vários turnos cria vantagem tática real.","perdeValor":"Perde muito valor quando Porta Dimensional (Dimension Door), Voo (Fly) ou deslocamento comum já resolvem a travessia, ou quando não há necessidade de manter dois pontos conectados por vários turnos.","obs2024":"2024: Ação, 500 pés, Concentração até 10 minutos. Cria dois portais vinculados em espaços Grandes e desocupados no chão que você possa ver: um a até 10 pés de você e outro dentro do alcance. Entrar pelo lado aberto de um portal faz sair pelo lado aberto do outro. Como Ação Bônus, você pode mudar a orientação dos lados abertos.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Cria dois portais conectados em pontos visíveis, permitindo que criaturas e objetos atravessem instantaneamente entre eles enquanto você mantiver Concentração.","notas":"Portal tático para deslocar repetidamente o grupo entre dois pontos visíveis por até 10 minutos. Pode transformar mapas grandes, mas compete pela única escolha de Arcano Místico de 6º nível e exige uma situação que realmente aproveite múltiplas travessias.","nivelLabel":"6º nível","funcoes":["Exploração","Utilidade"]},{"id":"MAG-0072","nomePt":"Círculo da Morte","nomeEn":"Circle of death","nivel":6,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Necromancia","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"45 m (150 ft) · esfera de raio 18 m (60 ft)","duracao":"Instantânea","componentes":"V, S, M","dano":"8d8 necrótico; metade no sucesso","material":"Pó de pérola negra de 500+ PO · não consumido","escalonamento":"+2d8 por nível de espaço acima do 6º; como Arcano Místico, o Bruxo normalmente conjura no 6º nível","funcao1":"Dano","funcao2":"Controle","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Não exige Concentração, então pode ser usado enquanto o Bruxo mantém Fome de Hadar (Hunger of Hadar), Banimento (Banishment) ou outra magia sustentada. O raio enorme permite atingir grupos muito espalhados quando o posicionamento dos aliados não é um problema.","tradeoffs":"Como Arcano Místico, é uma escolha diária muito valiosa para um efeito essencialmente de dano. A esfera de 60 pés afeta todas as criaturas na área, inclusive aliados, usa salvaguarda de Constituição e compete diretamente com Estática Sináptica (Synaptic Static), que o Bruxo já pode usar com espaços de Magia de Pacto e ainda aplica debuff.","melhorQuando":"Campo aberto ou grande grupo de inimigos dispersos onde a esfera de 60 pés consiga atingir muitos alvos sem alcançar aliados e dano imediato seja mais importante que controle ou utilidade.","perdeValor":"Perde prioridade contra poucos alvos, criaturas resistentes ou imunes a necrótico, campos misturados com aliados ou quando controle e utilidade valem mais que uma grande explosão de dano.","obs2024":"2024: Ação, 150 pés, Esfera de 60 pés, Instantânea. Cada criatura na área faz salvaguarda de Constituição, sofrendo 8d8 necrótico em falha ou metade no sucesso. Exige pó de pérola negra esmagada no valor de 500+ PO. Upcast normal seria +2d8 por nível acima do 6º, mas o Arcano Místico de 6º nível do Bruxo é conjurado como magia de 6º nível.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Libera uma enorme explosão de energia necrótica em uma esfera de 60 pés, causando dano necrótico a todas as criaturas na área conforme a salvaguarda de Constituição.","notas":"Explosão necrótica de área colossal, com raio de 60 pés e sem Concentração. É forte quando consegue atingir muitos inimigos, mas como Arcano Místico concorre com opções que entregam controle, invocação ou utilidade por muito mais tempo.","nivelLabel":"6º nível","funcoes":["Dano","Controle"]},{"id":"MAG-0073","nomePt":"Criar Morto-Vivo","nomeEn":"Create undead","nivel":6,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Necromancia","concentracao":"Não","ritual":"Não","conjuracao":"1 minuto","alcance":"3 m (10 ft)","duracao":"Instantânea; controle por 24 horas","componentes":"V, S, M","dano":"— · dano vem dos servos criados","material":"1 ônix negro de 150+ PO por cadáver · não consumido","escalonamento":"Como Arcano Místico de 6º nível, o Bruxo conjura esta magia no 6º nível","funcao1":"Utilidade","funcao2":"Dano","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"A duração de controle de 24 horas encaixa muito bem com o uso uma vez por Descanso Longo do Arcano Místico: uma conjuração diária pode criar ou reafirmar controle sobre até três Carniçais. Não usa Concentração, deixando o Bruxo livre para sustentar outras magias em combate.","tradeoffs":"Só pode ser conjurada à noite, exige cadáveres de Humanoides Médios ou Pequenos e uma pedra de ônix negra de 150+ PO por cadáver. Os Carniçais já são relativamente frágeis no nível em que o Bruxo recebe o arcanum e manter o grupo sob controle consome a conjuração diária de 6º nível.","melhorQuando":"Campanha com tempo de preparação, acesso a cadáveres e utilidade para servos persistentes — guarda, exploração, pressão numérica ou absorção de riscos — quando manter até três Carniçais por 24 horas vale abrir mão de outro arcanum.","perdeValor":"Perde espaço em aventuras rápidas, locais sem cadáveres adequados, situações diurnas sem tempo para preparar a conjuração ou quando os Carniçais são frágeis demais para justificar o Arcano Místico diário.","obs2024":"2024: 1 minuto, 10 pés, Instantânea; só pode ser conjurada à noite. Escolhe até três cadáveres de Humanoides Médios ou Pequenos, que viram Carniçais sob seu controle por 24 horas. Com Ação Bônus, você comanda mentalmente os criados a até 120 pés; sem comando, usam Esquivar e evitam perigo. Repetir a magia antes de 24 horas reafirma o controle. Exige uma pedra de ônix negra de 150+ PO por cadáver.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Anima até três cadáveres de Humanoides como Carniçais sob seu controle por 24 horas, que podem receber comandos mentais enquanto estiverem ao alcance.","notas":"Cria até três Carniçais sob seu controle por 24 horas. Pode gerar presença persistente e utilidade fora de combate, mas no nível 11 esses servos já são frágeis e manter o controle consome sua conjuração diária de 6º nível.","nivelLabel":"6º nível","funcoes":["Utilidade","Dano"]},{"id":"MAG-0074","nomePt":"Mau Olhado","nomeEn":"Eyebite","nivel":6,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Necromancia","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"Pessoal · alvo a até 18 m (60 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Controle","funcao2":null,"prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Uma única conjuração pode tentar afetar uma criatura diferente a cada turno, permitindo ao Bruxo converter várias Ações em controle sem gastar novas magias. As opções Inconsciente, Amedrontado e Envenenado permitem adaptar o efeito ao tipo de inimigo e ao plano do grupo.","tradeoffs":"Exige Concentração e, após o primeiro alvo, cada novo uso consome sua Ação Mágica, competindo com Rajada Mística (Eldritch Blast). Alvos que passarem na salvaguarda não podem ser escolhidos novamente naquela conjuração; além disso, Inconsciente termina com dano/uma ação de despertar e o efeito de Pânico pode terminar se o alvo escapar para longe e perder sua visão.","melhorQuando":"Combate prolongado contra vários inimigos relevantes, quando neutralizar um alvo novo por rodada gera mais valor que usar a Ação para dano e o grupo consegue preservar os alvos Adormecidos ou explorar os Amedrontados/Envenenados.","perdeValor":"Cai em confrontos curtos, contra criaturas com Sabedoria alta ou quando sua Ação vale mais em dano imediato; também perde eficiência se os alvos podem ser acordados ou escapar facilmente dos efeitos.","obs2024":"2024: Ação, Pessoal, Concentração até 1 minuto. Um alvo visível a até 60 pés faz salvaguarda de Sabedoria; em falha você escolhe: Adormecido (Inconsciente até sofrer dano ou ser despertado com Ação), em Pânico (Amedrontado, deve Correr para longe e pode encerrar o efeito ao ficar a 60+ pés sem vê-lo) ou Adoecido (Envenenado). Em cada turno posterior, uma Ação Mágica pode tentar afetar outra criatura; quem passou na salvaguarda dessa conjuração não pode ser alvo novamente.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Imbui seus olhos com poder sobrenatural e, a cada turno, permite tentar colocar uma criatura para dormir, Amedrontá-la ou Envenená-la.","notas":"Controle sustentado que pode neutralizar uma criatura diferente a cada rodada com efeitos de sono, medo ou envenenamento. É excelente em encontros longos, desde que gastar sua Ação em novos alvos valha mais que Rajada Mística (Eldritch Blast).","nivelLabel":"6º nível","funcoes":["Controle"]},{"id":"MAG-0075","nomePt":"Invocar Corruptor","nomeEn":"Summon fiend","nivel":6,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"27 m (90 ft)","duracao":"Concentração, até 1 hora","componentes":"V, S, M","dano":"No 6º nível, 3 ataques: 1d12+9 necrótico / 1d8+9 cortante / 2d6+9 fogo","material":"Frasco com sangue de 600+ PO · não consumido","escalonamento":"O bloco usa o nível da magia; como Arcano Místico, o Bruxo conjura no 6º nível","funcao1":"Utilidade","funcao2":"Dano","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Demon, Devil e Yugoloth oferecem perfis diferentes para combate próximo, ataque à distância e mobilidade. O espírito age imediatamente após o Bruxo, obedece comandos verbais sem gastar Ação e pode gerar valor por até 1 hora, potencialmente atravessando mais de um encontro.","tradeoffs":"Exige Concentração e componente de 600+ PO. Como Arcano Místico de 6º nível, fica preso ao bloco de 6º nível e não aproveita o scaling de espaços superiores; manter o espírito também impede usar simultaneamente controles importantes que exigem Concentração.","melhorQuando":"Dia de aventura com combate prolongado ou vários encontros próximos, quando um aliado adicional por até 1 hora pode produzir dano, ocupar espaço e adaptar seu perfil ao matchup melhor do que um efeito instantâneo de uso único.","perdeValor":"Perde prioridade quando controle de área é mais importante, quando a Concentração precisa sustentar outro efeito ou quando o combate termina rápido demais para o espírito gerar valor sustentado.","obs2024":"2024: Ação, 90 pés, Concentração até 1 hora. Invoca um Espírito Ínfero e escolhe Demon, Devil ou Yugoloth, que altera detalhes do bloco. O espírito compartilha sua Iniciativa, age logo depois de você e obedece comandos verbais sem exigir Ação. Exige frasco ensanguentado de 600+ PO. Normalmente o bloco usa o nível da magia; como Arcano Místico de 6º nível, o Bruxo o conjura no 6º nível.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Invoca um espírito ínfero em forma de Demônio, Diabo ou Yugoloth, com características diferentes conforme a forma, que luta ao seu lado por até 1 hora.","notas":"Invocação de alto impacto por até 1 hora, com perfis Demon, Devil ou Yugoloth. É uma escolha forte de Arcano Místico porque pode gerar dano, presença de campo e utilidade por vários encontros próximos.","nivelLabel":"6º nível","funcoes":["Utilidade","Dano"]},{"id":"MAG-0076","nomePt":"Caldeirão Borbulhante de Tasha","nomeEn":"Tasha’s bubbling cauldron","nivel":6,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"1,5 m (5 ft)","duracao":"10 minutos","componentes":"V, S, M","dano":"—","material":"Concha dourada de 500+ PO · não consumida","escalonamento":"Não escala; usar espaço superior não altera o efeito","funcao1":"Utilidade","funcao2":"Defesa","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"O Arcano Místico uma vez por Descanso Longo combina muito bem com uma magia de preparação: o Bruxo pode produzir um número de poções Comuns ou Incomuns igual ao modificador de Carisma e distribuí-las ao grupo sem gastar Concentração. Carisma 20 normalmente significa até cinco poções por conjuração.","tradeoffs":"Exige uma concha dourada de 500+ PO e só produz um único tipo de poção por conjuração. O caldeirão não pode ser movido, dura apenas 10 minutos e as poções não consumidas desaparecem quando você conjura a magia novamente; escolher esta opção também ocupa seu único Arcano Místico de 6º nível.","melhorQuando":"Antes de uma missão ou descanso, quando o grupo pode transformar uma conjuração diária em várias poções de cura, resistência ou outra utilidade Comum/Incomum escolhida para os desafios previstos.","perdeValor":"Perde prioridade em campanhas com acesso fácil a poções, pouco tempo de preparação, baixa demanda por consumíveis ou quando ocupar o único Arcano Místico de 6º nível não compensa a economia criada.","obs2024":"2024: Ação, 5 pés, duração 10 minutos, sem Concentração. Conjura um caldeirão imóvel cujo líquido replica as propriedades de uma poção Comum ou Incomum à sua escolha. Você ou um aliado retira uma poção como Ação Bônus; o caldeirão produz um número igual ao seu modificador da habilidade de conjuração (mínimo 1). Poções não consumidas desaparecem quando você conjura esta magia novamente. Exige concha dourada de 500+ PO.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Cria um caldeirão mágico que produz várias doses de uma poção Comum ou Incomum escolhida por você, retiradas como Ação Bônus enquanto a magia durar.","notas":"Converte uma única conjuração diária em várias poções Comuns ou Incomuns que permanecem até serem consumidas ou até você conjurar a magia novamente. Para grupos que planejam antes da aventura, é uma das opções de utilidade mais eficientes do nível.","nivelLabel":"6º nível","funcoes":["Utilidade","Defesa"]},{"id":"MAG-0077","nomePt":"Visão da Verdade","nomeEn":"True seeing","nivel":6,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Adivinhação","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"Toque · Visão Verdadeira 36 m (120 ft)","duracao":"1 hora","componentes":"V, S, M","dano":"—","material":"Pó de cogumelo de 25+ PO · consumido","escalonamento":"Não escala","funcao1":"Exploração","funcao2":"Utilidade","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Não usa Concentração e concede Visão Verdadeira de 120 pés por 1 hora, sendo uma resposta direta a ilusões, invisibilidade e outros efeitos que dependem de enganar a visão. Pode ser aplicada a qualquer criatura voluntária por Toque.","tradeoffs":"Consome pó de cogumelo de 25+ PO e, principalmente, ocupa a única escolha de Arcano Místico de 6º nível para uma necessidade que pode não aparecer na maioria dos dias. Nos níveis mais altos, a Invocação Visão de Bruxa (Witch Sight) também reduz parte dessa necessidade para o próprio Bruxo.","melhorQuando":"Aventura em que ilusões, criaturas invisíveis, metamorfos ou efeitos visuais mágicos são uma ameaça central e garantir Visão Verdadeira por 1 hora vale mais que dano, invocação ou controle.","perdeValor":"Perde muito valor quando Invisibilidade, ilusões e metamorfos são raros, quando outro membro do grupo já possui Visão Verdadeira ou quando Visão de Bruxa (Witch Sight) cobre a necessidade do próprio Bruxo.","obs2024":"2024: Ação, Toque, duração 1 hora, sem Concentração. Uma criatura voluntária recebe Visão Verdadeira (Truesight) com alcance de 120 pés. Consome pó de cogumelo no valor de 25+ PO.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Concede Visão Verdadeira (Truesight) a uma criatura voluntária por 1 hora, permitindo perceber com clareza efeitos e criaturas que a visão comum não revela dentro do alcance.","notas":"Visão Verdadeira (Truesight) de 120 pés por 1 hora, sem Concentração. É extremamente confiável quando ilusões e Invisibilidade dominam a aventura, mas estreita demais para ser a escolha padrão do único Arcano Místico de 6º nível.","nivelLabel":"6º nível","funcoes":["Exploração","Utilidade"]},{"id":"MAG-0078","nomePt":"Forma Etérea","nomeEn":"Etherealness","nivel":7,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"Pessoal","duracao":"Até 8 horas","componentes":"V, S","dano":"—","material":"—","escalonamento":"Espaços superiores permitem incluir criaturas adicionais; isso não se aplica ao Arcano Místico de 7º nível do Bruxo","funcao1":"Exploração","funcao2":"Utilidade","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Exploração, infiltração e fuga ganham muito com até 8 horas no Plano Etéreo, permitindo atravessar obstáculos e evitar interação com criaturas do plano de origem. Como não exige Concentração, o Bruxo não corre o risco de perder o efeito por dano comum.","tradeoffs":"Como Arcano Místico (Mystic Arcanum) de 7º nível, ocupa a única escolha desse nível e normalmente afeta apenas o próprio Bruxo, pois o benefício de alvos adicionais exige espaço de 8º nível ou maior. Também não funciona em planos que não fazem fronteira com o Etéreo, como os Planos Exteriores.","melhorQuando":"Infiltração profunda, fuga, exploração de áreas inacessíveis ou travessia de barreiras durante várias horas, quando permanecer praticamente fora de alcance do plano material vale mais que uma opção direta de combate.","perdeValor":"Perde prioridade em campanhas com pouco conteúdo planar, quando mobilidade comum já resolve a exploração ou quando uma escolha de 7º nível voltada apenas ao próprio Bruxo não gera valor suficiente.","obs2024":"2024: Ação, Pessoal, duração 8 horas, sem Concentração. Você entra na Fronteira Etérea e pode se mover em qualquer direção; percebe o plano de origem de forma limitada e normalmente só interage com criaturas, objetos e efeitos no Plano Etéreo. Ao terminar, retorna ao ponto correspondente; se estiver ocupado, é deslocado e sofre dano de Força. Upcast permite incluir criaturas adicionais, mas isso não se aplica ao Arcano Místico de 7º nível do Bruxo.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Transporta você para a Fronteira Etérea por até 8 horas, permitindo mover-se pelo Plano Etéreo e retornar depois ao ponto correspondente no plano de origem.","notas":"Exploração e infiltração extrema por até 8 horas no Plano Etéreo, sem Concentração. É excelente quando atravessar obstáculos e sair do alcance do plano material resolve a missão, mas como Arcano Místico de 7º nível normalmente beneficia apenas o próprio Bruxo.","nivelLabel":"7º nível","funcoes":["Exploração","Utilidade"]},{"id":"MAG-0079","nomePt":"Dedo da Morte","nomeEn":"Finger of death","nivel":7,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Necromancia","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"18 m (60 ft)","duracao":"Instantânea","componentes":"V, S","dano":"7d8 + 30 necrótico; metade no sucesso","material":"—","escalonamento":"Não escala","funcao1":"Dano","funcao2":"Utilidade","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Não exige Concentração, então pode ser usado enquanto o Bruxo mantém Fome de Hadar (Hunger of Hadar), Banimento (Banishment) ou outra magia sustentada. Se matar um Humanoide, o Zumbi criado adiciona presença persistente no campo e pode continuar útil depois do encontro.","tradeoffs":"É uma única explosão de dano contra um alvo e usa salvaguarda de Constituição, frequentemente alta em monstros robustos. Como única escolha de Arcano Místico de 7º nível, compete com controle extremo de Jaula de Força (Forcecage) e utilidade planar; o benefício do Zumbi depende de matar especificamente um Humanoide.","melhorQuando":"Contra um alvo prioritário já enfraquecido ou vulnerável a dano necrótico, especialmente um Humanoide cuja morte possa gerar um Zumbi útil após o combate.","perdeValor":"Perde prioridade em encontros com muitos alvos, resistência ou imunidade a necrótico, Constituição alta ou quando controle de 7º nível gera mais impacto que dano de alvo único.","obs2024":"2024: Ação, 60 pés, Instantânea. Uma criatura visível faz salvaguarda de Constituição: sofre 7d8 + 30 necrótico em falha ou metade no sucesso. Um Humanoide morto por esta magia se ergue no início do seu próximo turno como um Zumbi que segue suas ordens verbais. Não exige Concentração.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Atinge uma criatura com intensa energia necrótica; se um Humanoide morrer por causa da magia, ele se ergue como um Zumbi que segue suas ordens.","notas":"Explosão de dano necrótico de alvo único sem Concentração, com metade do dano mesmo no sucesso. Se matar um Humanoide, ainda cria um Zumbi obediente, dando algum valor persistente além do dano inicial.","nivelLabel":"7º nível","funcoes":["Dano","Utilidade"]},{"id":"MAG-0080","nomePt":"Cárcere de Energia","nomeEn":"Forcecage","nivel":7,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Evocação","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"30 m (100 ft)","duracao":"Concentração, até 1 hora","componentes":"V, S, M","dano":"—","material":"Pó de rubi de 1.500+ PO · consumido","escalonamento":"Não escala","funcao1":"Controle","funcao2":"Defesa","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Excelente para separar um inimigo perigoso do combate sem salvaguarda inicial. O formato de caixa bloqueia matéria e magias atravessando a barreira, enquanto o formato de jaula permite controlar espaço; aliados podem usar o tempo ganho para resolver o restante do encontro ou preparar uma resposta.","tradeoffs":"A versão 2024 foi enfraquecida em relação à 2014: agora exige Concentração e consome pó de rubi de 1.500+ PO. Criaturas grandes demais não ficam presas e teleporte/viagem planar ainda podem permitir fuga após salvaguarda de Carisma; além disso, manter a jaula impede sustentar outra magia de Concentração.","melhorQuando":"Contra um inimigo extremamente perigoso que caiba completamente na área e cuja remoção temporária permita ao grupo transformar um encontro difícil em dois confrontos separados.","perdeValor":"Perde prioridade quando o custo consumido de 1.500+ PO é proibitivo, quando o alvo é grande demais para a área ou dispõe de teleporte/viagem planar confiável para tentar escapar.","obs2024":"2024: Ação, 100 pés, Concentração até 1 hora. Cria prisão Invisível de força em formato de jaula de até 20 pés por lado ou caixa sólida de até 10 pés por lado. Criaturas completamente dentro ficam presas sem salvaguarda inicial; criaturas grandes demais são empurradas para fora. Teleporte ou viagem planar exigem salvaguarda de Carisma para escapar. Estende-se ao Plano Etéreo e não pode ser dissipada por Dissipar Magia (Dispel Magic). Consome pó de rubi de 1.500+ PO.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Cria uma prisão invisível de força em forma de jaula ou caixa sólida, confinando criaturas completamente dentro da área sem salvaguarda inicial.","notas":"Controle de elite sem salvaguarda inicial: prende completamente uma criatura que caiba na área e pode transformar um combate difícil em dois encontros separados. Em 2024 continua fortíssima, mas agora cobra Concentração e um componente consumido muito caro.","nivelLabel":"7º nível","funcoes":["Controle","Defesa"]},{"id":"MAG-0081","nomePt":"Viagem Planar","nomeEn":"Plane shift","nivel":7,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"Toque","duracao":"Instantânea","componentes":"V, S, M","dano":"—","material":"Haste metálica bifurcada de 250+ PO, sintonizada ao plano · não consumida","escalonamento":"Não escala","funcao1":"Exploração","funcao2":null,"prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Permite levar até oito criaturas voluntárias para outro plano com uma única Ação, funcionando como ferramenta de campanha para viagens planares, fuga extrema e acesso a locais que nenhuma magia de mobilidade inferior alcança.","tradeoffs":"Como única escolha de Arcano Místico de 7º nível, é muito dependente da campanha e exige uma haste metálica bifurcada de 250+ PO sintonizada com o plano de destino. Na versão 2024, perdeu a antiga aplicação ofensiva de banir uma criatura involuntária, ficando focada em transporte de criaturas voluntárias.","melhorQuando":"Campanhas planares ou momentos em que o grupo inteiro precisa viajar imediatamente para outro plano e já possui o componente sintonizado correto para o destino.","perdeValor":"Perde muito valor em campanhas que não exigem deslocamento entre planos; como única escolha de 7º nível, é difícil justificar quando a haste sintonizada não está disponível ou outra opção impacta a campanha com mais frequência.","obs2024":"2024: Ação, Toque, Instantânea. Você e até oito criaturas voluntárias de mãos dadas são transportados para outro plano. Pode indicar o destino em termos gerais, com o ponto exato determinado pelo Mestre, ou usar a sequência de um círculo de teletransporte conhecido naquele plano. Exige uma haste metálica bifurcada de 250+ PO sintonizada com o plano. A versão 2024 não inclui a antiga opção ofensiva de banir uma criatura involuntária.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Transporta você e até oito criaturas voluntárias para outro plano de existência, usando um foco sintonizado com o plano de destino.","notas":"Transporte planar instantâneo para o grupo inteiro. É uma ferramenta de campanha poderosa quando viajar entre planos realmente importa, mas a versão 2024 perdeu a antiga função ofensiva e depende de possuir a haste sintonizada correta.","nivelLabel":"7º nível","funcoes":["Exploração"]},{"id":"MAG-0082","nomePt":"Perturbação Mental","nomeEn":"Befuddlement","nivel":8,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"45 m (150 ft)","duracao":"Instantânea","componentes":"V, S, M","dano":"10d12 psíquico; metade no sucesso","material":"Argola com chaves ausentes · sem custo indicado · não consumida","escalonamento":"Não escala","funcao1":"Dano","funcao2":"Controle","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Brilha contra conjuradores e criaturas que dependem da ação Magia (Magic): além de 10d12 psíquico, uma falha bloqueia conjuração de magias e a ação Magia por um período potencialmente muito longo. Não exigir Concentração permite manter outro controle simultaneamente.","tradeoffs":"Depende de salvaguarda de Inteligência; em sucesso, vira apenas dano pela metade e perde completamente o bloqueio mágico. Contra inimigos que pouco usam magia, boa parte do valor tático desaparece, embora o dano continue relevante.","melhorQuando":"Contra um conjurador, usuário frequente da ação Magia ou chefe mágico cuja neutralização valha a única escolha de Arcano Místico de 8º nível.","perdeValor":"Perde prioridade contra inimigos puramente marciais, quando dano em área ou controle coletivo é mais importante ou quando a salvaguarda de Inteligência do alvo é suficientemente alta para tornar o bloqueio incerto.","obs2024":"2024: Ação, 150 pés, Instantânea. Um alvo visível faz salvaguarda de Inteligência. Em falha, sofre 10d12 psíquico e não pode conjurar magias nem usar a ação Magia (Magic). Repete a salvaguarda ao fim de cada 30 dias, encerrando o efeito em sucesso; Restauração Maior (Greater Restoration), Cura (Heal) ou Desejo (Wish) também encerram. Em sucesso, sofre apenas metade do dano.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Devasta a mente de uma criatura com dano psíquico e, em falha na salvaguarda de Inteligência, impede-a de conjurar magias e usar a ação Magia por um período prolongado.","notas":"Explosão psíquica pesada contra um único alvo que, em falha, também desliga conjuração de magias e a ação Magia (Magic) por um período potencialmente enorme. Contra conjuradores, pode decidir um encontro sem exigir Concentração.","nivelLabel":"8º nível","funcoes":["Dano","Controle"]},{"id":"MAG-0083","nomePt":"Semiplano","nomeEn":"Demiplane","nivel":8,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"18 m (60 ft)","duracao":"1 hora","componentes":"S","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Utilidade","funcao2":"Exploração","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Pode funcionar como depósito extradimensional, esconderijo temporário ou ponto de acesso recorrente: conjurações futuras podem reconectar a um semiplano criado anteriormente e até a um semiplano de outra criatura cujo conteúdo e natureza sejam conhecidos.","tradeoffs":"Não oferece impacto imediato de combate comparável às outras opções de 8º nível e ocupa a única escolha de Arcano Místico desse nível. A porta dura apenas 1 hora; criaturas que permanecerem dentro depois disso ficam no semiplano até conseguirem sair por nova conexão ou outro meio.","melhorQuando":"Campanhas com preparação, armazenamento, esconderijos e logística extradimensional, quando ter um espaço persistente de 30 pés por dimensão gera valor recorrente entre aventuras.","perdeValor":"Perde muito valor em campanhas lineares ou com pouca logística, onde um refúgio, depósito ou espaço extradimensional persistente raramente resolve problemas importantes.","obs2024":"2024: Ação, 60 pés, duração 1 hora, sem Concentração. Cria uma porta Média em uma superfície sólida que leva a uma sala extradimensional vazia de 30 pés em cada dimensão. Ao conjurar novamente, pode criar outro semiplano ou reconectar a um criado anteriormente; também pode conectar a um semiplano criado por outra criatura se conhecer sua natureza e conteúdo.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Cria uma porta para um semiplano extradimensional próprio, que pode servir como sala persistente e ser reconectado por conjurações futuras.","notas":"Cria um espaço extradimensional persistente que pode virar depósito, esconderijo ou ponto logístico recorrente. É uma ferramenta de campanha muito flexível, mas difícil de justificar como única escolha de Arcano Místico de 8º nível em aventuras focadas em combate.","nivelLabel":"8º nível","funcoes":["Utilidade","Exploração"]},{"id":"MAG-0084","nomePt":"Dominar Monstro","nomeEn":"Dominate monster","nivel":8,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"18 m (60 ft)","duracao":"Concentração, até 1 hora","componentes":"V, S","dano":"—","material":"—","escalonamento":"No 9º nível, a Concentração aumenta para até 8 horas; o Arcano Místico de 8º nível do Bruxo não faz esse upcast","funcao1":"Controle","funcao2":"Utilidade","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"A ligação telepática permite dar ordens sem gastar Ação, inclusive direcionando ataques, movimento e tarefas; o Bruxo pode até comandar uma Reação do alvo ao gastar a própria Reação. Funciona contra qualquer criatura e não apenas Humanoides.","tradeoffs":"Exige Concentração e salvaguarda de Sabedoria; o alvo tem Vantagem se já estiver lutando contra você ou seus aliados. Além disso, sempre que sofre dano repete a salvaguarda, então transformar o alvo em aliado durante um combate aberto pode ser instável.","melhorQuando":"Antes ou no início de um conflito contra uma criatura poderosa que possa ser convertida em recurso do grupo, especialmente quando você consegue evitar causar dano ao alvo e explorar suas próprias ações contra outros inimigos.","perdeValor":"Cai em lutas já iniciadas, contra imunidade a Enfeitiçado (Charmed), Sabedoria alta ou quando o grupo não consegue evitar causar dano ao alvo e permitir novas salvaguardas.","obs2024":"2024: Ação, 60 pés, Concentração até 1 hora. Uma criatura faz salvaguarda de Sabedoria, com Vantagem se você ou seus aliados estiverem lutando contra ela. Em falha fica Enfeitiçada. Você mantém ligação telepática no mesmo plano e pode dar ordens sem Ação; para comandar uma Reação, gasta sua própria Reação. Sempre que o alvo sofre dano, repete a salvaguarda. Upcast de 9º nível aumenta a Concentração para até 8 horas, mas o Arcano Místico de 8º nível do Bruxo não faz esse upcast.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Tenta dominar mentalmente uma criatura, deixando-a Enfeitiçada e permitindo dar ordens telepáticas sem gastar Ação enquanto você mantiver Concentração.","notas":"Controle de altíssimo teto: transforma uma criatura poderosa em recurso do grupo por até 1 hora, com ordens telepáticas sem gastar Ação. Funciona melhor antes do combate ou quando o grupo consegue evitar atacar o alvo dominado.","nivelLabel":"8º nível","funcoes":["Controle","Utilidade"]},{"id":"MAG-0085","nomePt":"Eloquência","nomeEn":"Glibness","nivel":8,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"Pessoal","duracao":"1 hora","componentes":"V","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Social","funcao2":"Utilidade","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"O Bruxo usa Carisma como atributo principal, então substituir qualquer resultado baixo por 15 transforma testes de Persuasão, Enganação, Intimidação e outros testes de Carisma em resultados extremamente consistentes. A proteção contra magia que detecta mentira reforça infiltração e negociação.","tradeoffs":"Não ajuda diretamente em combate e seu valor depende de a campanha realmente recompensar cenas sociais, negociação e intriga. Como única escolha de Arcano Místico de 8º nível, compete com opções que podem decidir encontros de combate imediatamente.","melhorQuando":"Audiências, interrogatórios, negociações, infiltração social ou cenas políticas em que uma hora de resultados de Carisma excepcionalmente consistentes possa alterar o rumo da aventura.","perdeValor":"Cai para quase zero em campanhas focadas em combate ou exploração, quando poucas cenas dependem de testes de Carisma ou quando outra personagem já resolve consistentemente a parte social.","obs2024":"2024: Ação, Pessoal, duração 1 hora, sem Concentração. Sempre que você fizer um teste de Carisma, pode substituir o número rolado no d20 por 15. Além disso, magia que determine se você está dizendo a verdade indica que suas declarações são verdadeiras. Em 2024, a escola é Encantamento; a versão Legacy/2014 era Transmutação.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Eleva sua eloquência por 1 hora, permitindo substituir resultados baixos em testes de Carisma por 15 e fazendo magias detectoras de mentira tratarem suas declarações como verdadeiras.","notas":"Uma hora de testes de Carisma extremamente consistentes para uma classe que já prioriza Carisma. Em intriga, negociação e infiltração social pode ser devastadora sem exigir Concentração, mas seu valor cai muito em campanhas pouco sociais.","nivelLabel":"8º nível","funcoes":["Social","Utilidade"]},{"id":"MAG-0086","nomePt":"Palavra de Poder: Atordoar","nomeEn":"Power word stun","nivel":8,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"18 m (60 ft)","duracao":"Instantânea; condição persiste até salvaguarda bem-sucedida","componentes":"V","dano":"—","material":"—","escalonamento":"Não escala","funcao1":"Controle","funcao2":"Defesa","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Não exige Concentração nem salvaguarda inicial para atordoar um alvo com 150 PV ou menos, então pode ser usada enquanto o Bruxo mantém outro efeito e cria uma janela confiável para o grupo concentrar ataques. Reduzir previamente os PV do alvo aumenta muito a consistência.","tradeoffs":"O limite de 150 PV é decisivo: acima dele, o efeito reduz apenas o Deslocamento a 0 até o início do seu próximo turno. Alvos Atordoados ainda fazem salvaguarda de Constituição ao fim de cada turno para encerrar a condição, e Constituição costuma ser forte em monstros de alto nível.","melhorQuando":"Contra um inimigo importante já reduzido a 150 PV ou menos, quando garantir Atordoado imediatamente — sem teste inicial e sem gastar Concentração — pode abrir uma rodada decisiva para o grupo.","perdeValor":"Perde valor contra inimigos ainda muito acima de 150 PV, quando zerar Deslocamento por uma rodada não muda o encontro ou quando Constituição alta tende a encerrar Atordoado rapidamente.","obs2024":"2024: Ação, 60 pés, Instantânea. Se o alvo tiver 150 PV ou menos, fica Atordoado sem salvaguarda inicial. Se tiver mais de 150 PV, seu Deslocamento fica 0 até o início do seu próximo turno. Enquanto Atordoado, faz salvaguarda de Constituição ao fim de cada turno, encerrando a condição em sucesso. A versão 2024 adiciona o efeito de Deslocamento 0 quando o alvo está acima do limite, em vez de simplesmente não produzir efeito.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Pronuncia uma palavra de poder que Atordoa imediatamente uma criatura com 150 PV ou menos; acima desse limite, reduz seu Deslocamento a 0 até o início do seu próximo turno.","notas":"Controle imediato sem salvaguarda inicial quando o alvo está em 150 PV ou menos. Como não exige Concentração, pode criar uma rodada decisiva enquanto o Bruxo mantém outro efeito importante ativo.","nivelLabel":"8º nível","funcoes":["Controle","Defesa"]},{"id":"MAG-0087","nomePt":"Projeção Astral","nomeEn":"Astral projection","nivel":9,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Necromancia","concentracao":"Não","ritual":"Não","conjuracao":"1 hora","alcance":"3 m (10 ft)","duracao":"Até ser dissipada","componentes":"V, S, M","dano":"—","material":"Por alvo: jacinto de 1.000+ PO + barra de prata de 100+ PO · ambos consumidos","escalonamento":"Não escala","funcao1":"Exploração","funcao2":null,"prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Permite levar o grupo inteiro ao Plano Astral e, a partir dele, alcançar outros planos mantendo os corpos em animação suspensa. Como não exige Concentração, dano normal à forma astral não força testes para manter a magia.","tradeoffs":"Tempo de conjuração de 1 hora e custo consumido muito alto por alvo: uma jacinta de 1.000+ PO e uma barra de prata de 100+ PO para cada criatura. Como única escolha de Arcano Místico de 9º nível, é difícil justificar fora de campanhas em que viagem astral seja central.","melhorQuando":"Expedições planares deliberadas em que todo o grupo precisa viajar pelo Plano Astral ou alcançar outro plano por esse caminho e já dispõe dos componentes consumíveis necessários.","perdeValor":"Quase não entrega valor em campanhas que não usam o Plano Astral ou viagem planar, e o custo consumido por criatura pode tornar a conjuração impraticável mesmo quando o efeito seria útil.","obs2024":"2024: 1 hora, 10 pés, duração até ser dissipada, sem Concentração. Você e até oito criaturas voluntárias projetam formas astrais no Plano Astral enquanto os corpos ficam Inconscientes em animação suspensa. Cada alvo exige uma jacinta de 1.000+ PO e uma barra de prata de 100+ PO, ambas consumidas. Se a forma astral deixa o Plano Astral para outro plano, corpo e posses seguem pelo cordão prateado.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Projeta você e até oito criaturas para o Plano Astral, deixando os corpos físicos Inconscientes em animação suspensa até que as formas astrais retornem ou sigam para outro plano.","notas":"Expedição planar para o grupo inteiro: projeta até nove criaturas no Plano Astral e pode servir como rota para outros planos. É poderosa quando a campanha exige exatamente isso, mas o custo por alvo e a única escolha de Arcano Místico de 9º nível tornam a opção extremamente especializada.","nivelLabel":"9º nível","funcoes":["Exploração"]},{"id":"MAG-0088","nomePt":"Lâmina do Desastre","nomeEn":"Blade of disaster","nivel":9,"grupo":"Arcano Místico","fonte":"Heroes of Faerûn (HoF)","tagFonte":"HoF","escola":"Conjuração","concentracao":"Sim","ritual":"Não","conjuracao":"Ação Bônus","alcance":"18 m (60 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S","dano":"2 ataques por rodada; 10d6 força por acerto; crítico em 18–20","material":"—","escalonamento":"Não escala","funcao1":"Dano","funcao2":"Controle","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"A conjuração e os ataques usam Ação Bônus, deixando a Ação principal livre para Rajada Mística (Eldritch Blast), movimentação tática ou outra ação. A lâmina atravessa barreiras, inclusive Muralha de Força (Wall of Force), e seus críticos em 18–20 tornam Vantagem nos ataques especialmente valiosa.","tradeoffs":"Exige Concentração, depende de jogadas de ataque e ocupa a única escolha de Arcano Místico de 9º nível. Apesar do dano sustentado enorme, perder Concentração cedo reduz drasticamente o retorno; também não combina simultaneamente com outras magias de Concentração.","melhorQuando":"Chefe ou alvo resistente que permanecerá em combate por várias rodadas, especialmente quando o Bruxo consegue proteger a Concentração e usar a Ação principal para continuar contribuindo enquanto a lâmina ataca com Ação Bônus.","perdeValor":"Perde valor em encontros curtos, quando sua Concentração precisa sustentar controle mais importante, quando os ataques têm baixa chance de acertar ou quando perder Concentração cedo desperdiça grande parte do potencial.","obs2024":"Heroes of Faerûn, regras 2024: Ação Bônus, 60 pés, Concentração até 1 minuto. Cria uma fissura planar em forma de lâmina e imediatamente faz até dois ataques mágicos corpo a corpo contra criaturas ou objetos a até 5 pés dela. Cada acerto causa 10d6 de Força e é crítico com resultado 18–20 no d20. Em turnos posteriores, Ação Bônus move a lâmina até 60 pés e repete os dois ataques. A lâmina atravessa barreiras, inclusive Muralha de Força (Wall of Force).","fonteOficial":"https://www.dndbeyond.com/sources/dnd/frhof","oQueFaz":"Invoca uma lâmina planar que realiza até dois ataques devastadores de força como Ação Bônus, pode ser reposicionada a cada turno e atravessa barreiras mágicas.","notas":"Opção HoF de dano sustentado brutal: cria uma lâmina planar que faz até dois ataques imediatamente e repete os ataques com Ação Bônus nos turnos seguintes, deixando sua Ação livre para Rajada Mística (Eldritch Blast) ou outra contribuição.","nivelLabel":"9º nível","funcoes":["Dano","Controle"]},{"id":"MAG-0089","nomePt":"Premonição","nomeEn":"Foresight","nivel":9,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Adivinhação","concentracao":"Não","ritual":"Não","conjuracao":"1 minuto","alcance":"Toque","duracao":"8 horas","componentes":"V, S, M","dano":"—","material":"Pena de beija-flor · sem custo indicado · não consumida","escalonamento":"Não escala","funcao1":"Defesa","funcao2":"Dano","prioridadeN":4,"classificacao":"ESSENCIAL","sinergias":"Oito horas sem Concentração combinam perfeitamente com o Bruxo: o alvo recebe Vantagem em todos os Testes d20 enquanto inimigos têm Desvantagem nos ataques contra ele, e o Bruxo continua livre para sustentar Fome de Hadar (Hunger of Hadar), Banimento (Banishment) ou outra magia de Concentração.","tradeoffs":"Afeta apenas uma criatura e não gera efeito ofensivo explosivo imediato. O principal custo é ocupar a única escolha de Arcano Místico de 9º nível, então grupos com necessidades muito específicas de transformação, dano ou viagem planar podem preferir outra ferramenta.","melhorQuando":"Dia de aventura importante com vários encontros, especialmente em um personagem que fará muitos ataques, salvaguardas e testes e que será alvo frequente de ataques durante as próximas 8 horas.","perdeValor":"Permanece relevante praticamente sempre; perde prioridade apenas quando a aventura exige um efeito de 9º nível mais específico, como viagem planar ou transformação.","obs2024":"2024: 1 minuto, Toque, duração 8 horas, sem Concentração. Uma criatura voluntária recebe Vantagem em todos os Testes d20 pela duração, e outras criaturas têm Desvantagem nas jogadas de ataque contra ela. A magia termina cedo se você a conjurar novamente.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Concede a uma criatura percepção sobrenatural por 8 horas, dando Vantagem em todos os Testes d20 enquanto outras criaturas têm Desvantagem nas jogadas de ataque contra ela.","notas":"Buff de referência para o 9º nível: 8 horas sem Concentração dando Vantagem em todos os Testes d20 ao alvo e Desvantagem nos ataques feitos contra ele. O efeito é amplo, consistente e pode atravessar vários encontros.","nivelLabel":"9º nível","funcoes":["Defesa","Dano"]},{"id":"MAG-0090","nomePt":"Portal","nomeEn":"Gate","nivel":9,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Conjuração","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"18 m (60 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S, M","dano":"—","material":"Diamante de 5.000+ PO · não consumido","escalonamento":"Não escala","funcao1":"Exploração","funcao2":"Utilidade","prioridadeN":2,"classificacao":"ÓTIMO","sinergias":"Pode conectar diretamente dois planos para transportar o grupo ou trazer uma criatura específica de outro plano ao seu lado sem salvaguarda inicial. Em campanhas planares, resolve deslocamento e convocação com uma precisão que Viagem Planar (Plane Shift) não oferece.","tradeoffs":"Exige Concentração e um diamante de 5.000+ PO. Trazer uma criatura nomeada não concede qualquer controle sobre ela, então a magia pode colocar um inimigo perigosíssimo ao lado do grupo. Divindades e governantes planares também podem impedir a abertura do portal em seus domínios.","melhorQuando":"Campanha planar, resgate ou deslocamento estratégico em que abrir uma passagem precisa entre planos — ou trazer deliberadamente uma criatura específica — tenha impacto maior que uma opção de combate mais direta.","perdeValor":"Perde prioridade em campanhas quase inteiramente materiais ou quando o Mestre controla o acesso planar por outras rotas narrativas.","obs2024":"2024: Ação, 60 pés, Concentração até 1 minuto. Cria um portal de 5 a 20 pés de diâmetro para uma localização precisa em outro plano. Ao pronunciar o nome verdadeiro de uma criatura específica que esteja em outro plano, o portal pode abrir ao lado dela e transportá-la para o seu lado; a magia não concede controle sobre essa criatura. Exige diamante de 5.000+ PO, não indicado como consumido.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Abre um portal entre planos para um local específico ou pode chamar uma criatura conhecida até você através desse portal.","notas":"Portal interplanar preciso para deslocar o grupo ou trazer uma criatura específica de outro plano. Resolve problemas que poucas magias conseguem, mas convocar uma criatura pelo nome não concede qualquer controle sobre ela.","nivelLabel":"9º nível","funcoes":["Exploração","Utilidade"]},{"id":"MAG-0091","nomePt":"Aprisionamento","nomeEn":"Imprisonment","nivel":9,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Abjuração","concentracao":"Não","ritual":"Não","conjuracao":"1 minuto","alcance":"9 m (30 ft)","duracao":"Até ser dissipada","componentes":"V, S, M","dano":"—","material":"Estatueta do alvo de 5.000+ PO · não consumida","escalonamento":"Não escala","funcao1":"Controle","funcao2":"Utilidade","prioridadeN":1,"classificacao":"SITUACIONAL","sinergias":"Se o alvo falhar na salvaguarda, o efeito pode neutralizá-lo por anos e oferece cinco formas de prisão com aplicações narrativas diferentes. Não exige Concentração e só pode ser encerrado por condições específicas ou Dissipar Magia (Dispel Magic) usando espaço de 9º nível.","tradeoffs":"Tempo de conjuração de 1 minuto, salvaguarda de Sabedoria, estatueta de 5.000+ PO e exigência de definir um gatilho de término que o Mestre considere altamente provável de ocorrer na próxima década tornam o uso em combate extremamente difícil. Como único Arcano Místico de 9º nível, é um custo de oportunidade enorme.","melhorQuando":"Depois que um inimigo já foi dominado, contido ou incapacitado, quando o objetivo é removê-lo da história por longo prazo em vez de simplesmente derrotá-lo em combate.","perdeValor":"Perde quase todo o valor em combate espontâneo; é uma ferramenta de história, ritual e resolução de ameaças capturadas.","obs2024":"2024: 1 minuto, 30 pés, duração até ser dissipada. Salvaguarda de Sabedoria; em falha, o alvo fica aprisionado e não precisa respirar, comer ou beber, não envelhece, não pode ser localizado por Adivinhação e não pode se teleportar. Escolha entre Burial, Chaining, Hedged Prison, Minimus Containment ou Slumber. Ao conjurar, deve definir um gatilho observável de término com alta probabilidade de ocorrer na próxima década. Dissipar Magia só encerra se for conjurada com espaço de 9º nível. Exige estatueta do alvo de 5.000+ PO.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Aprisiona uma criatura por tempo potencialmente indefinido em uma das várias formas mágicas de confinamento, impedindo fuga e localização por Adivinhação.","notas":"Ferramenta de remoção narrativa de longo prazo. Se a salvaguarda falhar, pode neutralizar uma criatura por anos sem Concentração, mas o tempo de conjuração e as exigências de preparação tornam seu uso em combate normal pouco prático.","nivelLabel":"9º nível","funcoes":["Controle","Utilidade"]},{"id":"MAG-0092","nomePt":"Palavra de Poder: Matar","nomeEn":"Power word kill","nivel":9,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Encantamento","concentracao":"Não","ritual":"Não","conjuracao":"Ação","alcance":"18 m (60 ft)","duracao":"Instantânea","componentes":"V","dano":"Morte automática com 100 PV ou menos; caso contrário 12d12 psíquico","material":"—","escalonamento":"Não escala","funcao1":"Dano","funcao2":"Controle","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Não exige jogada de ataque, salvaguarda ou Concentração. Contra alvo com mais de 100 PV, ainda causa 12d12 psíquico; contra 100 PV ou menos, mata automaticamente. Funciona bem como finalizador depois que o grupo reduz os PV de um chefe, mas nunca é uma conjuração completamente desperdiçada pela antiga barreira de 100 PV.","tradeoffs":"Afeta apenas uma criatura e, contra alvos acima de 100 PV, entrega somente dano de alvo único. Resistência ou imunidade a psíquico reduz o valor quando não ocorre a execução, e outras opções de 9º nível podem gerar valor por várias rodadas ou transformar o encontro de maneiras mais amplas.","melhorQuando":"Contra um alvo prioritário quando você quer resultado imediato e extremamente confiável: execução automática abaixo de 101 PV ou uma grande explosão de dano sem teste quando ele ainda está acima desse limiar.","perdeValor":"Perde prioridade contra muitos inimigos, alvos com PV muito acima do limiar ou quando transformação/controle de 9º nível pode decidir mais que dano bruto.","obs2024":"2024: Ação, 60 pés, Instantânea. Uma criatura visível com 100 PV ou menos morre automaticamente. Se tiver mais de 100 PV, sofre 12d12 psíquico. Não exige jogada de ataque, salvaguarda ou Concentração. Essa é uma melhora importante sobre a versão Legacy/2014, que não produzia efeito acima de 100 PV.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Pronuncia uma palavra que mata instantaneamente uma criatura com 100 PV ou menos; se ela estiver acima desse limite, ainda sofre grande dano psíquico.","notas":"Finalizador extremamente confiável: abaixo de 101 PV o alvo morre sem teste; acima disso ainda sofre 12d12 psíquico sem jogada de ataque ou salvaguarda. A versão 2024 eliminou o risco de gastar o arcanum e não produzir efeito.","nivelLabel":"9º nível","funcoes":["Dano","Controle"]},{"id":"MAG-0093","nomePt":"Polimorfia Verdadeira","nomeEn":"True polymorph","nivel":9,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Transmutação","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"9 m (30 ft)","duracao":"Concentração, até 1 hora; após 1 hora completa, até ser dissipada","componentes":"V, S, M","dano":"—","material":"Mercúrio, goma-arábica e fumaça · sem custo indicado · não consumidos","escalonamento":"Não escala","funcao1":"Utilidade","funcao2":"Controle","prioridadeN":4,"classificacao":"ESSENCIAL","sinergias":"Pode transformar criatura em outra criatura, criatura em objeto ou objeto em criatura. Se a Concentração for mantida pela hora completa, o efeito passa a durar até ser dissipado, dando ao Bruxo uma ferramenta de combate, utilidade, infiltração e transformação permanente em um único arcanum.","tradeoffs":"Exige Concentração por 1 hora para tornar o efeito duradouro e criaturas involuntárias recebem salvaguarda de Sabedoria. Pela errata de 2025, esgotar os PV temporários não encerra mais a magia; porém, na transformação criatura→criatura o alvo ainda não pode falar nem conjurar magias, reduzindo o valor de formas cuja força depende de Spellcasting. Proteger a Concentração continua essencial até completar a hora.","melhorQuando":"Quando a campanha recompensa máxima flexibilidade: transformar um aliado em criatura poderosa, neutralizar um inimigo, criar uma criatura a partir de objeto ou produzir uma transformação duradoura depois de uma hora segura de Concentração.","perdeValor":"Permanece relevante em praticamente qualquer campanha; perde prioridade somente quando outro Arcano Místico de 9º nível resolve de forma mais direta o problema específico.","obs2024":"2024 + errata 2025: Ação, 30 pés, Concentração até 1 hora. Transforma criatura em criatura, criatura em objeto ou objeto não mágico em criatura. Um alvo involuntário faz salvaguarda de Sabedoria. Se a Concentração durar a hora completa, a transformação passa a durar até ser dissipada. Em criatura→criatura, a nova forma pode ter ND até o ND ou nível do alvo; o alvo mantém seus PV e Dados de Vida e recebe PV temporários iguais aos PV da nova forma. A errata substituiu a cláusula que encerrava a magia ao zerar esses PV temporários: agora eles apenas desaparecem se ainda restarem quando a magia termina. O alvo transformado continua sem poder falar ou conjurar magias.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Transforma completamente uma criatura ou objeto em outra criatura ou objeto; se você mantiver Concentração pela hora completa, a transformação passa a durar até ser dissipada.","notas":"Uma das opções mais flexíveis do jogo: transforma criatura em criatura, criatura em objeto ou objeto em criatura, e pode tornar a transformação duradoura após uma hora completa de Concentração. A errata vigente também removeu o antigo encerramento ao perder os PV temporários.","nivelLabel":"9º nível","funcoes":["Utilidade","Controle"]},{"id":"MAG-0094","nomePt":"Estranheza","nomeEn":"Weird","nivel":9,"grupo":"Arcano Místico","fonte":"PHB 2024","tagFonte":"Core 2024","escola":"Ilusão","concentracao":"Sim","ritual":"Não","conjuracao":"Ação","alcance":"36 m (120 ft) · esfera de raio 9 m (30 ft)","duracao":"Concentração, até 1 minuto","componentes":"V, S","dano":"10d10 psíquico inicial; +5d10 no fim de cada turno em nova falha","material":"—","escalonamento":"Não escala","funcao1":"Dano","funcao2":"Controle","prioridadeN":3,"classificacao":"PRIORIDADE","sinergias":"Escolhe as criaturas dentro de uma Esfera de 30 pés, evitando fogo amigo. Alvos que falham sofrem grande dano psíquico e ficam Amedrontados; enquanto continuarem falhando nas salvaguardas ao fim dos turnos, sofrem mais 5d10 por rodada.","tradeoffs":"Exige Concentração e salvaguarda de Sabedoria. Em sucesso, o alvo sofre apenas metade dos 10d10 iniciais e não fica Amedrontado nem recebe dano recorrente; criaturas imunes ou resistentes a psíquico/Amedrontado reduzem parte importante do valor.","melhorQuando":"Grande grupo de inimigos dentro de uma área de 30 pés quando o Bruxo quer combinar explosão inicial alta, seleção de alvos e controle/dano recorrente sobre quem falhar.","perdeValor":"Perde prioridade contra poucos inimigos, resistência/imunidade psíquica ou grupos imunes a Frightened.","obs2024":"2024: Ação, 120 pés, Esfera de 30 pés, Concentração até 1 minuto. Criaturas à sua escolha fazem salvaguarda de Sabedoria. Em falha, sofrem 10d10 psíquico e ficam Amedrontadas pela duração; em sucesso, sofrem metade do dano apenas. Alvo Amedrontado repete a salvaguarda ao fim de cada turno: em falha sofre 5d10 psíquico adicionais; em sucesso, a magia termina para ele.","fonteOficial":"https://www.dndbeyond.com/sources/dnd/br-2024/spell-descriptions","oQueFaz":"Invoca pesadelos em uma grande área, causando dano psíquico e Amedrontando criaturas escolhidas; falhas repetidas mantêm o medo e causam dano adicional.","notas":"Explosão seletiva de terror psíquico: 10d10 iniciais em uma grande área, com Amedrontado e potencial de 5d10 adicionais por rodada nos alvos que continuarem falhando. É dano e controle em um único Arcano Místico.","nivelLabel":"9º nível","funcoes":["Dano","Controle"]}];

const FILTERS = {
  functions:["Todas","Dano","Controle","Defesa","Utilidade","Exploração","Social"],
  schools:["Todas","Abjuração","Adivinhação","Conjuração","Encantamento","Evocação","Ilusão","Necromancia","Transmutação"],
  sources:["Todas","Core 2024","HoF"],
  levels:["Todos","Truques","1º","2º","3º","4º","5º","6º","7º","8º","9º"],
  priorities:["Todas","ESSENCIAL","PRIORIDADE","ÓTIMO","SITUACIONAL"]
};

const state={q:"",fn:"Todas",school:"Todas",source:"Todas",level:"Todos",priority:"Todas",selected:SPELLS[0].id};

function esc(v){return String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[m]))}
function clsPriority(c){return "priority-"+String(c).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"")}
function sourceClass(s){return s==="HoF"?"source-hof":"source-core"}
function levelMatches(spell,val){
  if(val==="Todos") return true;
  if(val==="Truques") return spell.nivel===0;
  return spell.nivel===Number(val.replace("º",""));
}
function filtered(){
  const q=state.q.trim().toLowerCase();
  return SPELLS.filter(s=>{
    const hay=[s.nomePt,s.nomeEn,s.funcao1,s.funcao2,s.dano,s.notas,s.sinergias,s.obs2024].filter(Boolean).join(" ").toLowerCase();
    return (!q||hay.includes(q))
      && (state.fn==="Todas"||s.funcoes.includes(state.fn))
      && (state.school==="Todas"||s.escola===state.school)
      && (state.source==="Todas"||s.tagFonte===state.source)
      && levelMatches(s,state.level)
      && (state.priority==="Todas"||s.classificacao===state.priority);
  });
}
function buildPills(targetId,values,key,mobile=false){
  const el=document.getElementById(targetId); el.innerHTML="";
  values.forEach(val=>{
    const b=document.createElement("button");
    b.className="pill"+(key==="source"&&val==="HoF"?" hof":"");
    b.textContent=(key==="source"&&val==="HoF")?"Heróis de Faerûn":val;
    b.dataset.value=val;
    if(state[key]===val)b.classList.add("active");
    b.onclick=()=>{state[key]=val; renderFilters(); render(); if(mobile) closeSheets();};
    el.appendChild(b);
  });
}
function renderFilters(){
  buildPills("fmmg-functionPills",FILTERS.functions,"fn");
  buildPills("fmmg-schoolPills",FILTERS.schools,"school");
  buildPills("fmmg-sourcePills",FILTERS.sources,"source");
  buildPills("fmmg-levelPills",FILTERS.levels,"level");
  buildPills("fmmg-priorityPills",FILTERS.priorities,"priority");
  buildPills("fmmg-mFunctionPills",FILTERS.functions,"fn",true);
  buildPills("fmmg-mSchoolPills",FILTERS.schools,"school",true);
  buildPills("fmmg-mSourcePills",FILTERS.sources,"source",true);
  buildPills("fmmg-mLevelPills",FILTERS.levels,"level",true);
  buildPills("fmmg-mPriorityPills",FILTERS.priorities,"priority",true);
}
function rowTemplate(s){
  return `<button class="spell-row ${state.selected===s.id?"selected":""}" data-id="${esc(s.id)}">
    <div class="spell-name"><strong>${esc(s.nomePt)}</strong><small>${esc(s.nomeEn)}</small>
      <div class="row-tags"><span class="row-tag">${esc(s.funcao1)}</span>${s.funcao2?`<span class="row-tag">${esc(s.funcao2)}</span>`:""}<span class="row-tag"><i class="source-dot ${s.tagFonte==="HoF"?"hof":""}"></i>${esc(s.tagFonte)}</span></div>
    </div>
    <div class="level-cell">${esc(s.nivelLabel)}</div>
    <div><span class="priority-mini ${clsPriority(s.classificacao)}">${esc(s.classificacao)}</span></div>
  </button>`;
}
function detailTemplate(s, mobile=false){
  return `<div class="fmmg-detail">
    <div class="detail-top">
      <div><h2>${esc(s.nomePt)} <span class="school-inline">(${esc(s.escola)})</span></h2><div class="en-name">${esc(s.nomeEn)}</div></div>
      <div class="detail-chips">
        <span class="chip">${esc(s.nivelLabel)}</span>
        <span class="chip ${sourceClass(s.tagFonte)}">${esc(s.tagFonte)}</span>
        <span class="chip ${clsPriority(s.classificacao)}">${esc(s.classificacao)}</span>
        ${s.funcoes.map(f=>`<span class="chip">${esc(f)}</span>`).join("")}
      </div>
    </div>
    <div class="what-does">
      <label>O que faz</label>
      <div>${esc(s.oQueFaz)}</div>
    </div>
    <div class="detail-summary"><strong>Leitura Forja:</strong> ${esc(s.notas)}</div>
    <div class="mech-grid">
      <div class="mech"><label>Conjuração</label><div>${esc(s.conjuracao)}</div></div>
      <div class="mech"><label>Alcance</label><div>${esc(s.alcance)}</div></div>
      <div class="mech"><label>Duração</label><div>${esc(s.duracao)}</div></div>
      <div class="mech"><label>Componentes</label><div>${esc(s.componentes)}</div></div>
      <div class="mech"><label>Concentração</label><div>${esc(s.concentracao)}</div></div>
      <div class="mech"><label>Ritual</label><div>${esc(s.ritual)}</div></div>
    </div>
    <div class="secondary-grid">
      <div class="data-block"><label>Dano</label><div>${esc(s.dano)}</div></div>
      <div class="data-block"><label>Material / Consumo</label><div>${esc(s.material)}</div></div>
      <div class="data-block"><label>Escalonamento</label><div>${esc(s.escalonamento)}</div></div>
    </div>
    <div class="analysis-grid">
      <div class="editor-card good"><label>Melhor quando</label><div>${esc(s.melhorQuando)}</div></div>
      <div class="editor-card trade"><label>Trade-off</label><div>${esc(s.tradeoffs)}</div></div>
      <div class="editor-card loss"><label>Quando perde valor</label><div>${esc(s.perdeValor)}</div></div>
      <div class="editor-card"><label>Sinergias</label><div>${esc(s.sinergias)}</div></div>
    </div>
    <div class="notes-row">
      <div class="editor-card"><label>Observações 2024</label><div>${esc(s.obs2024)}</div></div>
      <div class="editor-card"><label>Fonte</label><div>${esc(s.fonte)}</div>
        <a class="source-link" href="${esc(s.fonteOficial)}" target="_blank" rel="noopener">Consultar fonte ↗</a>
      </div>
    </div>
  </div>`;
}
function renderDetail(s){
  document.getElementById("fmmg-detail").outerHTML = detailTemplate(s).replace('<div class="fmmg-detail">','<div class="fmmg-detail" id="fmmg-detail">');
  document.getElementById("fmmg-mobileDetail").innerHTML = detailTemplate(s,true);
}
function render(){
  const list=filtered();
  const listEl=document.getElementById("fmmg-spellList");
  const empty=document.getElementById("fmmg-emptyState");
  if(!list.length){
    listEl.innerHTML=""; empty.classList.add("show");
  }else{
    empty.classList.remove("show");
    if(!list.some(s=>s.id===state.selected))state.selected=list[0].id;
    listEl.innerHTML=list.map(rowTemplate).join("");
    listEl.querySelectorAll(".spell-row").forEach(btn=>btn.onclick=()=>{
      state.selected=btn.dataset.id; render();
      if(window.matchMedia("(max-width:820px)").matches)openDetail();
    });
    renderDetail(SPELLS.find(s=>s.id===state.selected));
  }
  document.getElementById("fmmg-resultCount").textContent=`${list.length} ${list.length===1?"resultado":"resultados"}`;
  const active=[];
  if(state.fn!=="Todas")active.push(state.fn);
  if(state.school!=="Todas")active.push(state.school);
  if(state.source!=="Todas")active.push(state.source);
  if(state.level!=="Todos")active.push(state.level==="Truques"?"Truques":`${state.level} nível`);
  if(state.priority!=="Todas")active.push(state.priority[0]+state.priority.slice(1).toLowerCase());
  document.getElementById("fmmg-activeState").textContent=active.length?active.join(" · "):"Todos os filtros";
  const changed=state.q||active.length;
  document.getElementById("fmmg-clearFilters").classList.toggle("visible",!!changed);
  document.getElementById("fmmg-mClearFilters").classList.toggle("visible",!!changed);
}
function resetFilters(){
  state.q="";state.fn="Todas";state.school="Todas";state.source="Todas";state.level="Todos";state.priority="Todas";
  document.getElementById("fmmg-search").value="";
  renderFilters();render();
}
function openFilters(){document.getElementById("fmmg-filterSheet").classList.add("open");document.getElementById("fmmg-backdrop").classList.add("open")}
function openDetail(){document.getElementById("fmmg-detailSheet").classList.add("open");document.getElementById("fmmg-backdrop").classList.add("open")}
function closeSheets(){
  document.getElementById("fmmg-filterSheet").classList.remove("open");
  document.getElementById("fmmg-detailSheet").classList.remove("open");
  document.getElementById("fmmg-backdrop").classList.remove("open");
}

document.getElementById("fmmg-search").addEventListener("input",e=>{state.q=e.target.value;render()});
document.getElementById("fmmg-clearFilters").onclick=resetFilters;
document.getElementById("fmmg-mClearFilters").onclick=resetFilters;
document.getElementById("fmmg-emptyReset").onclick=resetFilters;
document.getElementById("fmmg-openFilters").onclick=openFilters;
document.getElementById("fmmg-backdrop").onclick=closeSheets;
document.querySelectorAll("[data-close]").forEach(b=>b.onclick=closeSheets);

renderFilters();render();